package com.rankednh;

import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.WorldType;

/** Revision 241 native battle context and timer. Independent of API match state. */
final class ArenaCombat {
    static boolean inBattle(Client client){
        return client.getGameState()==GameState.LOGGED_IN && client.getWorldType().contains(WorldType.PVP_ARENA)
            && client.getRevision()==ArenaSetup.REVISION && client.getVarbitValue(14022)==1
            && (client.getVarbitValue(14017)==1 || client.getVarbitValue(14016)>0)
            // The challenge dialog is never a fight. Its shared-area flag can coexist with
            // timer/status values left over from the previous duel.
            && !ArenaSetup.visible(client,ArenaSetup.DUEL,0);
    }
}

package com.rankednh;

import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.TreeMap;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.WorldType;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;

/** Filters only the local Max/Med catalogue. Never changes a kit or dispatches a game action. */
@Singleton
final class ArenaItemCatalog {
    private static final int ROW_HEIGHT=32;
    private final Client client;
    private final DefaultArenaKit reference;
    private volatile boolean enabled=true;
    private volatile String notice="";
    private Widget list;
    private Widget[] children;
    private Set<Integer> shownItems=Set.of();
    private int originalHeight,originalScroll,filteredHeight;
    private final List<Cell> cells=new ArrayList<>();
    private static final class Cell {
        final Widget widget;
        final int y,itemId;
        final boolean hidden;
        int shownY;
        boolean shownHidden;
        Cell(Widget widget){this.widget=widget;y=widget.getOriginalY();itemId=widget.getItemId();hidden=widget.isSelfHidden();}
        boolean unchanged(){return widget.getOriginalY()==shownY && widget.isSelfHidden()==shownHidden && widget.getItemId()==itemId;}
    }
    @Inject ArenaItemCatalog(Client client,DefaultArenaKit reference){this.client=client;this.reference=reference;}
    void enabled(boolean value){enabled=value;if(!value)clear();}
    boolean enabled(){return enabled;}
    String notice(){return notice;}
    Widget visibleList(){
        if(client.getRevision()!=ArenaSetup.REVISION || client.getGameState()!=GameState.LOGGED_IN ||
            !client.getWorldType().contains(WorldType.PVP_ARENA))return null;
        // Never touch the opponent's catalogue or a different build's editor.
        int id=ArenaSetup.visible(client,ArenaSetup.DUEL,0)?InterfaceID.PvpArenaUnrankedduel._0ITEMS_LIST:
            InterfaceID.PvpArenaStagingareaSupplies._0ITEMS_LIST;
        Widget widget=client.getWidget(id);
        return widget==null || widget.isHidden()?null:widget;
    }
    void maintain(boolean active,ArenaKit kit){
        Widget current=active && enabled?visibleList():null;
        if(current==null){clear();return;}
        if(kit==null || !kit.complete()){clear();return;}
        Set<Integer> available=optional(kit).keySet();
        apply(current,available);
        if(available.isEmpty() && list!=null)notice="All default items are already included.";
    }
    void apply(Widget current,Set<Integer> allowed){
        if(list!=null){
            if(current==list && allowed.equals(shownItems) && intact())return;
            clear();
        }
        Widget[] items=current.getDynamicChildren();if(items==null || items.length==0)return;
        Map<Integer,List<Widget>> rows=new TreeMap<>();
        for(Widget child:items)if(child!=null){
            if(child.getOriginalY()<0)return;
            rows.computeIfAbsent(child.getOriginalY()/ROW_HEIGHT,k->new ArrayList<>()).add(child);
        }
        // Empty search results are valid; a layout with no item-bearing rows is not ours to reshape.
        if(rows.values().stream().noneMatch(row->row.stream().anyMatch(w->w.getItemId()>0)))return;
        list=current;children=items.clone();shownItems=Set.copyOf(allowed);originalHeight=current.getScrollHeight();originalScroll=current.getScrollY();
        int shown=0;
        for(Map.Entry<Integer,List<Widget>> row:rows.entrySet()){
            boolean keep=row.getValue().stream().anyMatch(w->allowed.contains(w.getItemId()));
            // Preserve the game's existing search results; filtering only narrows that list.
            boolean visible=keep && row.getValue().stream().anyMatch(w->!w.isSelfHidden());
            for(Widget widget:row.getValue()){
                Cell cell=new Cell(widget);cells.add(cell);
                cell.shownY=visible?shown*ROW_HEIGHT+cell.y-row.getKey()*ROW_HEIGHT:cell.y;
                cell.shownHidden=cell.hidden || !keep;
                widget.setHidden(cell.shownHidden);widget.setOriginalY(cell.shownY);widget.revalidate();
            }
            if(visible)shown++;
        }
        filteredHeight=shown*ROW_HEIGHT;
        notice=shown==0?"No missing approved items match this search.":"";
        current.setScrollHeight(filteredHeight);current.setScrollY(Math.min(originalScroll,Math.max(0,filteredHeight-current.getHeight())));
        current.revalidateScroll();
    }
    private boolean intact(){
        Widget[] live=list.getDynamicChildren();
        if(live==null || live.length!=children.length || list.getScrollHeight()!=filteredHeight)return false;
        for(int i=0;i<live.length;i++)if(live[i]!=children[i])return false;
        return cells.stream().allMatch(Cell::unchanged);
    }
    void clear(){
        if(list==null)return;
        // A native rebuild owns the new widgets. Do not overwrite it with an old snapshot.
        if(intact()){
            for(Cell cell:cells){cell.widget.setHidden(cell.hidden);cell.widget.setOriginalY(cell.y);cell.widget.revalidate();}
            list.setScrollHeight(originalHeight);list.setScrollY(originalScroll);list.revalidateScroll();
        }
        list=null;children=null;shownItems=Set.of();cells.clear();notice="";
    }
    Map<Integer,Integer> optional(ArenaKit kit){return kit==null || !kit.complete()?Map.of():kit.availableFrom(reference.kit());}
}

package com.rankednh;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/** A snapshot of configured supplies, not the player's lobby inventory or worn gear. */
final class ArenaKit
{
    static final int[] EQUIPMENT_SLOTS={0,1,2,3,4,5,7,9,10,12,13};
    static final String[] EQUIPMENT_NAMES={"Head","Cape","Neck","Weapon","Body","Shield","Legs","Hands","Feet","Ring","Ammo"};
    static final class Slot {
        final int itemId,quantity;
        final String name;
        Slot(int itemId,int quantity,String name){this.itemId=itemId;this.quantity=quantity;this.name=name;}
        boolean same(Slot other){return other!=null && itemId==other.itemId && quantity==other.quantity;}
    }
    final int revision,build,spellbook,runePouch;
    final List<Slot> equipment,inventory;
    String runeSelection;
    ArenaKit(int revision,int build,int spellbook,int runePouch,List<Slot> equipment,List<Slot> inventory){
        this.revision=revision;this.build=build;this.spellbook=spellbook;this.runePouch=runePouch;
        this.equipment=List.copyOf(equipment);this.inventory=List.copyOf(inventory);
    }
    boolean complete(){
        return equipment.size()==11 && inventory.size()==28 && spellbook>=0 && runePouch>=0 &&
            slots().stream().allMatch(s->s!=null && s.quantity>=0 && s.quantity<=5000 && (s.itemId>0?s.quantity>0:s.quantity==0));
    }
    private List<Slot> slots(){List<Slot> all=new ArrayList<>(equipment);all.addAll(inventory);return all;}
    /** Compare possession across both containers, including duplicate items and stack quantities. */
    Map<Integer,Integer> itemTotals(){
        Map<Integer,Integer> totals=new LinkedHashMap<>();
        for(Slot slot:slots())if(slot.itemId>0)totals.merge(slot.itemId,slot.quantity,Integer::sum);
        return totals;
    }
    /** Every default item is optional; the reference sets allowed IDs and maximum totals. */
    boolean allowedBy(ArenaKit reference){
        if(reference==null || !complete() || !reference.complete() || revision!=reference.revision ||
            build!=reference.build || spellbook!=reference.spellbook || runePouch!=reference.runePouch)return false;
        Map<Integer,Integer> limits=reference.itemTotals();
        return itemTotals().entrySet().stream().allMatch(e->e.getValue()<=limits.getOrDefault(e.getKey(),0));
    }
    Map<Integer,Integer> availableFrom(ArenaKit reference){
        Map<Integer,Integer> remaining=new LinkedHashMap<>(),actual=itemTotals();
        reference.itemTotals().forEach((id,max)->{int count=max-actual.getOrDefault(id,0);if(count>0)remaining.put(id,count);});
        return remaining;
    }
    List<String> differences(ArenaKit other){
        List<String> out=new ArrayList<>();
        if(other==null || !complete() || !other.complete()){out.add("Kit data unavailable");return out;}
        if(revision!=other.revision)out.add("Game version changed");
        if(build!=other.build)out.add("Build");
        if(!itemTotals().equals(other.itemTotals()))out.add("Items or quantities");
        if(spellbook!=other.spellbook)out.add("Spellbook");
        if(runePouch!=other.runePouch)out.add("Rune pouch");
        return out;
    }
    String spellbookName(){return spellbook==0?"Standard":spellbook==1?"Ancient Magicks":spellbook==2?"Lunar":spellbook==3?"Arceuus":"Unknown";}
    static final class Change {
        final String location,yours,theirs;final int equipment,inventory;
        final String actualLabel,expectedLabel;final boolean opponentSide;
        Change(String location,String yours,String theirs,int equipment,int inventory){this(location,yours,theirs,equipment,inventory,"Yours","Theirs",false);}
        Change(String location,String yours,String theirs,int equipment,int inventory,String actualLabel,String expectedLabel,boolean opponentSide){
            this.location=location;this.yours=yours;this.theirs=theirs;this.equipment=equipment;this.inventory=inventory;
            this.actualLabel=actualLabel;this.expectedLabel=expectedLabel;this.opponentSide=opponentSide;
        }
        String title(){return "Default".equals(expectedLabel) || "Allowed".equals(expectedLabel)?(opponentSide?"Opponent · ":"You · ")+location:location;}
        String summary(){return "Allowed".equals(expectedLabel) && theirs.startsWith("Not allowed")?theirs:
            actualLabel+": "+yours+"\n"+expectedLabel+": "+theirs;}
        String explanation(){return title()+"\n"+summary();}
    }
    static String item(Slot slot){return slot.itemId<=0?"Empty":slot.name+(slot.quantity>1?" × "+slot.quantity:"");}
    List<Change> changes(ArenaKit other){
        List<Change> changes=new ArrayList<>();if(other==null || !complete() || !other.complete())return changes;
        Map<Integer,Integer> actual=itemTotals(),expected=other.itemTotals();
        // One row per item type. Layout changes create no rows or red slot marks.
        for(Map.Entry<Integer,Integer> entry:expected.entrySet()){
            int id=entry.getKey(),have=actual.getOrDefault(id,0),need=entry.getValue();
            if(have<need){
                Slot named=other.first(id);int index=anchor(id,have,other);
                changes.add(itemChange(named,have,need,index));
            }
        }
        for(Map.Entry<Integer,Integer> entry:actual.entrySet()){
            int id=entry.getKey(),have=entry.getValue(),need=expected.getOrDefault(id,0);
            if(have>need)changes.add(itemChange(first(id),have,need,anchor(id,need,null)));
        }
        if(spellbook!=other.spellbook)changes.add(new Change("Spellbook",spellbookName(),other.spellbookName(),-1,-1));
        if(runePouch!=other.runePouch)changes.add(new Change("Rune pouch",runeSelection==null?"Check your rune selection":runeSelection,other.runeSelection==null?"Different rune selection":other.runeSelection,-1,pouchSlot()));
        return changes;
    }
    private Slot first(int id){for(Slot slot:slots())if(slot.itemId==id)return slot;throw new IllegalArgumentException("Missing item");}
    private Change itemChange(Slot named,int have,int need,int index){
        return new Change(named.name,have==0?"Missing":item(new Slot(named.itemId,have,named.name)),
            need==0?"Not required":item(new Slot(named.itemId,need,named.name)),index>=0 && index<11?index:-1,index>=11?index-11:-1);
    }
    private int anchor(int id,int allowed,ArenaKit expected){
        List<Slot> all=slots();int count=0,first=-1;
        for(int i=0;i<all.size();i++)if(all.get(i).itemId==id){
            if(first<0)first=i;
            count+=all.get(i).quantity;if(count>allowed)return i;
        }
        if(first>=0)return first; // Quantity shortage: point at an existing stack/item of this type.
        if(expected!=null){
            // A missing item has no actual position. Use an empty original worn slot or any empty
            // inventory slot as a hint; never mark a correctly owned item in its former position.
            for(int i=0;i<11;i++)if(expected.equipment.get(i).itemId==id && equipment.get(i).itemId<=0)return i;
            for(int i=0;i<28;i++)if(inventory.get(i).itemId<=0)return 11+i;
        }
        return -1;
    }
    private int pouchSlot(){for(int i=0;i<inventory.size();i++)if(inventory.get(i).itemId==27086)return i;return -1;}
    List<Change> defaultChanges(ArenaKit reference,boolean opponent){
        List<Change> out=new ArrayList<>();
        if(reference==null || !complete() || !reference.complete())return out;
        Map<Integer,Integer> limits=reference.itemTotals(),seen=new LinkedHashMap<>(),totals=itemTotals();
        List<Slot> all=slots();
        for(int i=0;i<all.size();i++){
            Slot slot=all.get(i);if(slot.itemId<=0)continue;
            int max=limits.getOrDefault(slot.itemId,0),count=seen.merge(slot.itemId,slot.quantity,Integer::sum);
            if(count>max)out.add(new Change(slot.name,item(new Slot(slot.itemId,totals.get(slot.itemId),slot.name)),
                max==0?"Not allowed. Remove this item.":"Up to "+max+" in total. Remove the extra.",
                i<11?i:-1,i>=11?i-11:-1,opponent?"Opponent":"Yours","Allowed",opponent));
        }
        if(spellbook!=reference.spellbook)out.add(new Change("Spellbook",spellbookName(),reference.spellbookName(),-1,-1,
            opponent?"Opponent":"Yours","Allowed",opponent));
        if(runePouch!=reference.runePouch)out.add(new Change("Rune pouch",runeSelection==null?"Check your rune selection":runeSelection,
            reference.runeSelection==null?"Different rune selection":reference.runeSelection,-1,pouchSlot(),opponent?"Opponent":"Yours","Allowed",opponent));
        return out;
    }
}

package com.rankednh;

import java.util.Objects;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.config.ConfigManager;

/** A saved-kit check belongs to one enrolled character, service and reference version. */
@Singleton
final class ArenaOnboarding {
    enum Step { HOP, CRATE, MAX_MED, FIX, CHECKING, READY }
    private final DefaultArenaKit reference;
    private final ReportSeenStore verified;
    private String owner;
    private long correctSince=-1;
    private boolean ready;
    private Step step=Step.HOP;

    @Inject ArenaOnboarding(DefaultArenaKit reference,ConfigManager config){
        this(reference,new ReportSeenStore(()->config.getConfiguration("rankednh","verifiedArenaKits"),
            value->config.setConfiguration("rankednh","verifiedArenaKits",value)));
    }
    ArenaOnboarding(DefaultArenaKit reference,ReportSeenStore verified){this.reference=reference;this.verified=verified;}

    void observe(String service,Models.Status status,boolean accountMatches,boolean arena,boolean fighting,
        boolean supplies,boolean maxMed,ArenaSetup.View setup,long now){
        String key=key(service,status);
        if(!Objects.equals(owner,key)){
            owner=key;ready=key!=null && verified.contains(key);correctSince=-1;
        }
        if(!accountMatches || key==null || fighting){correctSince=-1;return;}
        // A duel editor can also change the saved loadout. Invalidate future queue entry,
        // while the active match keeps its normal cancel, review and forfeit controls.
        if(arena && setup!=null && setup.kit!=null && setup.kit.complete() && !reference.matches(setup.kit)){
            ready=false;correctSince=-1;verified.forget(key);
        }
        if(supplies && maxMed && arena){
            boolean correct=setup!=null && !setup.warning && reference.matches(setup.kit);
            if(!correct){
                ready=false;correctSince=-1;verified.forget(key);step=Step.FIX;return;
            }
            if(!ready){
                if(correctSince<0)correctSince=now;
                // Two game ticks give the native editor time to populate all saved selectors.
                if(now-correctSince>=1200){verified.remember(key);ready=true;}
            }
            step=ready?Step.READY:Step.CHECKING;return;
        }
        correctSince=-1;
        step=ready?Step.READY:!arena?Step.HOP:supplies?Step.MAX_MED:Step.CRATE;
    }
    boolean canQueue(String service,Models.Status status,boolean accountMatches){
        if(!accountMatches || status==null || status.player==null)return false;
        if("demo".equals(status.mode))return true;
        return ready && Objects.equals(owner,key(service,status));
    }
    boolean restart(String service,Models.Status status,boolean accountMatches,boolean fighting){
        String key=key(service,status);
        if(key==null || !accountMatches || fighting || !idle(status) || "demo".equals(status.mode))return false;
        verified.forget(key);owner=key;ready=false;correctSince=-1;step=Step.HOP;
        return true;
    }
    void interrupt(){correctSince=-1;}
    Step step(){return step;}
    private String key(String service,Models.Status status){
        return service==null || status==null || status.player==null || status.player.id==null?null:
            service+"\n"+status.player.id+"\n"+reference.id();
    }
    static boolean idle(Models.Status s){return s!=null && !s.queued && (s.match==null || !s.match.isOpen());}
}

package com.rankednh;

/** Keeps the last challenge check across the transition into battle and across server review updates. */
final class ArenaRoundGuard {
    private final DefaultArenaKit defaultKit;
    @javax.inject.Inject ArenaRoundGuard(DefaultArenaKit defaultKit){this.defaultKit=defaultKit;}
    private String key;
    private ArenaSetup.View setup;
    private boolean entered;
    private volatile String code="",reason="";
    void reset(){key=null;setup=null;entered=false;code="";reason="";}
    void observe(Models.Status status,ArenaSetup.View view,boolean battle,boolean maxBuild){
        Models.Match match=status==null?null:status.match;
        if(match==null){reset();return;}
        String next=match.id+":"+match.round+":"+match.nonce;
        if(!next.equals(key)){reset();key=next;}
        if(!battle && !entered && view!=null)setup=view;
        if(!battle || entered || !("active".equals(match.state) || "reporting".equals(match.state)))return;
        entered=true;
        if(!maxBuild){code="build";reason="This fight is not using 126 combat with all combat stats at 99.";}
        else if(setup!=null && setup.warning){code="kit";reason=setup.message;}
        else if(setup==null || !setup.comparisonKnown || !defaultKit.matches(setup.kit) || !defaultKit.matches(setup.opponentKit)){
            code="unchecked";reason="Both kits were not checked before the fight started.";
        }
    }
    Models.SetupEvidence evidence(){return entered && !blocked() && setup!=null && setup.comparisonKnown?new Models.SetupEvidence(defaultKit.id(),setup.kit,setup.opponentKit):null;}
    void invalidateSetup(){if(!entered)setup=null;}
    void gameState(net.runelite.api.GameState state){
        // LOADING is the normal teleport into the fight; keep its just-checked setup.
        if(state==net.runelite.api.GameState.LOGIN_SCREEN || state==net.runelite.api.GameState.HOPPING || state==net.runelite.api.GameState.CONNECTION_LOST)invalidateSetup();
    }
    void checkConfigured(ArenaKit own){
        // These are saved setup selectors, not the worn items/inventory that change during combat.
        if(!entered || blocked())return;
        if(own==null){code="unchecked";reason="The configured kit could not be checked in the battle area.";}
        else if(!defaultKit.matches(own)){code="kit";reason="Your configured kit has an unapproved item, excess quantity or incorrect settings.";}
    }
    boolean blocked(){return !code.isEmpty();}
    String code(){return code;}
    String reason(){return reason;}
}

package com.rankednh;

import java.util.ArrayList;
import java.util.List;
import net.runelite.api.Client;
import net.runelite.api.EnumComposition;
import net.runelite.api.GameState;
import net.runelite.api.Item;
import net.runelite.api.ItemComposition;
import net.runelite.api.ItemContainer;
import net.runelite.api.WorldType;
import net.runelite.api.widgets.Widget;

/** Read-only Arena setup guidance. All reads run on the client thread. */
final class ArenaSetup
{
    // Revision 241 scripts 6202/6335: build 0 = Max/Med; progress <=1 = build selection.
    // Scripts 6321/6322/6311: A-kit slot selectors -> enum 4390; stackables receive 5,000.
    // Script 6325 maps configured spellbooks through enum 4389. Opponent container = 207.
    static final int REVISION=241,DUEL=757,SUPPLIES=758;
    private static final int[] INVENTORY_BITS={14032,14033,14034,14036,14037,14038,14040,14041,14042,
        14044,14045,14046,14047,14048,14049,14050,14051,14052,14053,14054,14055,14056,14057,14058,14059,14060,14061,14062};
    enum Target { NONE, MAX_MED_TAB, STATS_TAB, BUILD_CONFIRM, OPPONENT_TAB, KIT_CONFIRM }
    static final class View {
        final String heading,message,detail;
        final boolean warning;
        final ArenaKit kit;
        List<ArenaKit.Change> changes=java.util.List.of();
        boolean comparisonKnown;
        ArenaKit opponentKit;
        Target target=Target.NONE;
        View guide(Target target){this.target=target;return this;}
        View(String heading,String message,String detail,boolean warning,ArenaKit kit){
            this.heading=heading;this.message=message;this.detail=detail;this.warning=warning;this.kit=kit;
        }
    }
    private final DefaultArenaKit defaultKit;
    @javax.inject.Inject ArenaSetup(DefaultArenaKit defaultKit){this.defaultKit=defaultKit;}
    private ArenaKit confirmed;
    private String roundKey;
    private boolean wasDuel;
    void reset(){confirmed=null;roundKey=null;wasDuel=false;}
    static boolean visible(Client client,int group,int child){Widget w=client.getWidget(group,child);return w!=null && !w.isHidden();}
    View read(Client client,Models.Status status,boolean accountMatches,boolean fighting){
        if(!accountMatches || client.getGameState()!=GameState.LOGGED_IN || !client.getWorldType().contains(WorldType.PVP_ARENA)){
            reset();return null;
        }
        Models.Match match=status==null?null:status.match;
        boolean scoped=match!=null && ("preparing".equals(match.state) || "active".equals(match.state)) && client.getWorld()==match.world;
        if(match!=null && match.isOpen() && !scoped){reset();return null;}
        String key=scoped?match.id+":"+match.round:null;
        if(!java.util.Objects.equals(key,roundKey)){confirmed=null;roundKey=key;}
        boolean duel=visible(client,DUEL,0),supplies=visible(client,SUPPLIES,0);
        if(!duel || !wasDuel)confirmed=null;
        wasDuel=duel;
        if(!duel && !supplies || fighting)return null;
        if(client.getRevision()!=REVISION)return new View("Setup check unavailable","The Arena interface has changed.","Check Max/Med and both kits manually. Default kit not verified.",true,null);
        try{
            int build=client.getVarbitValue(14024),progress=client.getVarbitValue(14028);
            ArenaKit own=ownKit(client);
            own.runeSelection=runes(client,own.runePouch);
            if(!duel && !visible(client,SUPPLIES,9))return new View("Open Max/Med kit","Select the Max/Med kit tab to check your items.","Choose the duel build after challenging.",false,own).guide(Target.MAX_MED_TAB);
            if(scoped && duel){
                String title=widgetText(client,DUEL,2);
                if(title.startsWith("Unranked Duel: ") && !FightRecorder.normalized(title.substring(15)).equals(FightRecorder.normalized(match.opponent.rsn)))
                    return new View("Wrong opponent","Challenge "+match.opponent.rsn+" instead.","This duel is with another player.",true,own);
            }
            ArenaKit opponent=duel && progress>=2 && visible(client,DUEL,120)?opponentKit(client,build):null;
            if(opponent!=null)opponent.runeSelection=runes(client,opponent.runePouch);
            boolean accepted=duel && client.getVarbitValue(14029)==1;
            if(!accepted)confirmed=null;
            View result=describe(duel,progress,build,client.getVarbitValue(14026)==1,accepted,own,opponent,confirmed);
            if(duel && progress>=2)result=withGameCheck(result,widgetText(client,DUEL,55)+" "+widgetText(client,DUEL,142)+" "+widgetText(client,DUEL,145));
            // The supplies editor has no opponent to compare. Our own-kit rules determine readiness.
            if(accepted && confirmed==null && own.complete())confirmed=own;
            return result;
        }catch(RuntimeException unavailable){
            confirmed=null;
            return new View("Reading Arena setup","Waiting for the kit data…","Default kit not verified. Check the game's setup before confirming.",true,null);
        }
    }
    View describe(boolean duel,int progress,int build,boolean acceptedBuild,boolean acceptedKit,ArenaKit own,ArenaKit opponent,ArenaKit confirmed){
        if(duel && build!=0)return new View("Choose Max/Med","Select Max/Med in Stats.","Confirm the build together.",true,own).guide(Target.STATS_TAB);
        if(duel && progress<=1)return new View("Confirm build",acceptedBuild?"Waiting for your opponent.":"Max/Med selected. Confirm in-game.","Next: check both kits against the default.",false,own).guide(acceptedBuild?Target.NONE:Target.BUILD_CONFIRM);
        if(own==null || !own.complete())return new View("Reading kit","Open your Max/Med kit.","Waiting for the configured supplies.",true,null).guide(Target.MAX_MED_TAB);
        if(own.revision!=REVISION || opponent!=null && opponent.revision!=REVISION)
            return new View("Setup check unavailable","The game version differs from the default reference.","Update the plugin before fighting.",true,own);
        boolean yours=defaultKit.matches(own),theirs=defaultKit.matches(opponent);
        if(!yours || opponent!=null && opponent.complete() && !theirs){
            String heading=!yours?(opponent!=null && opponent.complete() && !theirs?"Fix both kits":"Fix your kit"):"Opponent needs to fix their kit";
            String recovery=yours?"Your kit is ready. Your opponent needs to fix the red-marked items or settings.":
                "Fix the marked items or settings in your kit. Any default item can be left out.";
            View view=new View(heading,"Use only approved items, within their quantity limits.",recovery,true,own);
            List<ArenaKit.Change> changes=new ArrayList<>(own.defaultChanges(defaultKit.kit(),false));
            if(opponent!=null && opponent.complete())changes.addAll(opponent.defaultChanges(defaultKit.kit(),true));
            if(!duel && changes.size()==1 && "Spellbook".equals(changes.get(0).location))
                view=new View(heading,"Choose Ancient Magicks.","Set the spellbook to Ancient Magicks in the Arena editor.",true,own);
            view.changes=List.copyOf(changes);
            view.target=!yours?Target.MAX_MED_TAB:Target.OPPONENT_TAB;
            return view;
        }
        if(!duel)return new View("Kit ready","Find a match in the NH panel.","Highlighted additions are optional. Arrange and equip approved items however you like.",false,own);
        if(confirmed!=null && !confirmed.differences(own).isEmpty())
            return new View("Kit changed","Your kit changed after confirmation.","Check both kits and confirm again.",true,own);
        if(opponent==null || !opponent.complete())return new View("Your kit is ready","Open Opponent's kit to check theirs.","Your items are allowed. Highlighted additions are optional.",false,own).guide(Target.OPPONENT_TAB);
        View matched=new View("Both kits ready",acceptedKit?"Waiting for your opponent.":"Both kits meet the Max/Med rules.",acceptedKit?"The duel starts when you have both confirmed.":"Click Confirm on Opponent's kit to enter the duel.",false,own).guide(acceptedKit?Target.NONE:Target.KIT_CONFIRM);
        matched.comparisonKnown=true;matched.opponentKit=opponent;return matched;
    }
    static View withGameCheck(View view,String text){
        // NH's complete comparison owns readiness. Native text can be stale or disagree
        // despite identical kits; it must not erase validated evidence or specific NH fixes.
        if(view.warning || view.comparisonKnown)return view;
        String plain=net.runelite.client.util.Text.removeTags(text).replace(' ',' ').toLowerCase(java.util.Locale.ROOT);
        if(plain.contains("does not match") || plain.contains("do not match")){
            return new View("Check opponent's kit","The opponent's full kit hasn't loaded yet.",
                "Open Opponent's kit so NH can check the items and settings.",true,view.kit).guide(Target.OPPONENT_TAB);
        }
        if(plain.contains("will not permit") || plain.contains("too many") || plain.contains("cannot be fired"))
            return new View("Check kit","The Arena has flagged a loadout problem.","Review the warning below the kit.",true,view.kit);
        return view;
    }
    private static String widgetText(Client client,int group,int child){
        Widget w=client.getWidget(group,child);return w==null || w.isHidden() || w.getText()==null?"":net.runelite.client.util.Text.removeTags(w.getText());
    }
    static ArenaKit ownKit(Client client){
        EnumComposition items=client.getEnum(4390),spellbooks=client.getEnum(4389);
        List<ArenaKit.Slot> equipment=new ArrayList<>(),inventory=new ArrayList<>();
        for(int i=0;i<11;i++)equipment.add(configuredSlot(client,items,client.getVarbitValue(14063+i)));
        for(int bit:INVENTORY_BITS)inventory.add(configuredSlot(client,items,client.getVarbitValue(bit)));
        return new ArenaKit(client.getRevision(),0,spellbooks.getIntValue(client.getVarbitValue(14035)),client.getVarpValue(3534),equipment,inventory);
    }
    private static ArenaKit.Slot configuredSlot(Client client,EnumComposition items,int selector){
        int id=items.getIntValue(selector);
        if(id<=0)return new ArenaKit.Slot(-1,0,"Empty");
        ItemComposition item=client.getItemDefinition(id);
        return new ArenaKit.Slot(id,item.isStackable()?5000:1,item.getName());
    }
    private static ArenaKit opponentKit(Client client,int build){
        // Native comparison script 6208 uses container 207. Prefer that transmitted data;
        // cached widget sprites can still show the previous kit while the native check changes.
        ItemContainer container=client.getItemContainer(207);
        if(container!=null && container.getItems().length>=42){
            List<ArenaKit.Slot> equipment=new ArrayList<>(),inventory=new ArrayList<>();
            for(int slot:ArenaKit.EQUIPMENT_SLOTS)equipment.add(containerSlot(client,container,slot));
            for(int i=0;i<28;i++)inventory.add(containerSlot(client,container,14+i));
            return new ArenaKit(client.getRevision(),build,client.getVarbitValue(14031),client.getVarpValue(3533),equipment,inventory);
        }
        // Widget data is a fallback while the full transmitted container is unavailable.
        Widget inventoryWidget=client.getWidget(DUEL,140);
        Widget[] displayed=inventoryWidget==null?null:inventoryWidget.getDynamicChildren();
        if(displayed!=null && displayed.length>=28){
            List<ArenaKit.Slot> worn=new ArrayList<>(),bag=new ArrayList<>();boolean complete=true;
            for(int i=0;i<11;i++){
                Widget slot=client.getWidget(DUEL,129+i);if(slot==null){complete=false;break;}
                Widget[] children=slot.getDynamicChildren();if(children==null){complete=false;break;}
                ArenaKit.Slot item=new ArenaKit.Slot(-1,0,"Empty");
                for(Widget child:children)if(child!=null && child.getItemId()>0)item=widgetSlot(client,child);
                worn.add(item);
            }
            for(int i=0;i<28;i++){if(displayed[i]==null){complete=false;break;}bag.add(widgetSlot(client,displayed[i]));}
            // Empty widgets can be loading placeholders. A genuinely empty opponent kit is
            // allowed, but it needs the full transmitted container above as evidence.
            if(complete && (worn.stream().anyMatch(s->s.itemId>0) || bag.stream().anyMatch(s->s.itemId>0)))
                return new ArenaKit(client.getRevision(),build,client.getVarbitValue(14031),client.getVarpValue(3533),worn,bag);
        }
        return null;
    }
    private static ArenaKit.Slot widgetSlot(Client client,Widget widget){
        int id=widget.getItemId();return id<=0?new ArenaKit.Slot(-1,0,"Empty"):
            new ArenaKit.Slot(id,widget.getItemQuantity(),client.getItemDefinition(id).getName());
    }
    static String runes(Client client,int mask){
        // Native editor 6424 offers Enable for set bits: the mask records EXCLUDED runes.
        if(mask==0)return "All runes enabled";
        EnumComposition types=client.getEnum(982);List<String> names=new ArrayList<>();
        for(int bit=0;bit<=23;bit++)if((mask & (1<<bit))!=0){int item=types.getIntValue(bit);if(item>0)names.add(client.getItemDefinition(item).getName());}
        return names.isEmpty()?"Rune selection unavailable":"Disabled: "+String.join(", ",names);
    }
    private static ArenaKit.Slot containerSlot(Client client,ItemContainer container,int slot){
        Item item=container.getItem(slot);
        return item==null || item.getId()<=0?new ArenaKit.Slot(-1,0,"Empty"):
            new ArenaKit.Slot(item.getId(),item.getQuantity(),client.getItemDefinition(item.getId()).getName());
    }
}

package com.rankednh;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.util.LinkedHashMap;
import java.util.Map;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.tooltip.Tooltip;
import net.runelite.client.ui.overlay.tooltip.TooltipManager;
import net.runelite.client.util.Text;

/** Marks the setting to fix, independently of which tab contains Confirm. Never intercepts input. */
final class ArenaSetupWarningOverlay extends Overlay {
    static final Color WARNING=new Color(239,107,100);
    static final Color NEXT=RankedNhPanel.ACCENT;
    private final Client client;
    private final RankedNhPlugin plugin;
    private final TooltipManager tooltips;
    private final ArenaItemCatalog catalog;
    ArenaSetupWarningOverlay(Client client,RankedNhPlugin plugin){this(client,plugin,null,null);}
    @Inject ArenaSetupWarningOverlay(Client client,RankedNhPlugin plugin,TooltipManager tooltips,ArenaItemCatalog catalog){
        this.client=client;this.plugin=plugin;this.tooltips=tooltips;this.catalog=catalog;
        setPosition(OverlayPosition.DYNAMIC);setLayer(OverlayLayer.MANUAL);setMovable(false);
        drawAfterInterface(ArenaSetup.DUEL);drawAfterInterface(ArenaSetup.SUPPLIES);
    }
    @Override public Dimension render(Graphics2D graphics){
        ArenaSetup.View view=plugin.setupView();
        if(view==null || !plugin.accountMatches() || client.getGameState()!=GameState.LOGGED_IN)return null;
        boolean duel=visible(ArenaSetup.DUEL,0)!=null;
        int group=duel?ArenaSetup.DUEL:ArenaSetup.SUPPLIES;
        if(!duel && visible(group,0)==null && visible(group,9)==null)return null;
        if(duel && "Choose Max/Med".equals(view.heading)){
            Widget choices=visible(group,10),target=findText(choices,"Max/Med",0);
            if(target!=null)drawBuildWarning(graphics,target.getBounds());
            else guide(graphics,group,"Stats",WARNING);
            return null;
        }
        switch(view.target){
            case MAX_MED_TAB:
                if(visible(group,duel?25:9)==null)guide(graphics,group,"Max/Med kit",view.warning?WARNING:NEXT);
                break;
            case OPPONENT_TAB:
                if(duel && visible(group,120)==null)guide(graphics,group,"Opponent's kit",view.warning?WARNING:NEXT);
                break;
            case BUILD_CONFIRM: case KIT_CONFIRM:
                if(duel && !view.warning)guide(graphics,group,"Confirm",NEXT);
                break;
            default:break;
        }
        drawOptional(graphics,view);
        if(!view.warning)return null;
        Map<Rectangle,ArenaKit.Change> marked=new LinkedHashMap<>();
        for(ArenaKit.Change change:view.changes){
            if(!duel && change.opponentSide)continue;
            if(change.equipment>=0)mark(visible(group,(!duel?18:change.opponentSide?129:33)+change.equipment),change,marked);
            if(change.inventory>=0){
                Widget inventory=visible(group,!duel?29:change.opponentSide?140:44);
                Widget[] children=inventory==null?null:inventory.getDynamicChildren();
                if(children!=null && children.length>change.inventory)mark(children[change.inventory],change,marked);
            }
            if("Spellbook".equals(change.location))mark(visible(group,!duel?10:change.opponentSide?121:25),change,marked);
        }
        drawSlots(graphics,marked.keySet());
        if(tooltips!=null){
            net.runelite.api.Point mouse=client.getMouseCanvasPosition();
            // One tooltip even when an item and its rune configuration share the same slot.
            for(Map.Entry<Rectangle,ArenaKit.Change> entry:marked.entrySet())if(entry.getKey().contains(mouse.getX(),mouse.getY())){
                tooltips.add(new Tooltip(RankedNhPanel.escape(entry.getValue().explanation()).replace("\n","<br>")));break;
            }
        }
        return null;
    }
    private void drawOptional(Graphics2D graphics,ArenaSetup.View view){
        if(catalog==null || view.kit==null || "Wrong opponent".equals(view.heading))return;
        Widget list=catalog.visibleList();if(list==null)return;
        Map<Integer,Integer> additions=catalog.optional(view.kit);
        Widget[] children=list.getDynamicChildren();if(children==null)return;
        Rectangle clip=list.getBounds();Graphics2D g=(Graphics2D)graphics.create();
        try{
            g.clip(clip);
            for(Widget item:children)if(item!=null && !item.isHidden() && additions.containsKey(item.getItemId())){
                Rectangle bounds=item.getBounds();if(bounds.width<=0 || bounds.height<=0 || !bounds.intersects(clip))continue;
                int count=additions.get(item.getItemId());drawAddition(g,bounds,count);
                if(tooltips!=null){net.runelite.api.Point mouse=client.getMouseCanvasPosition();
                    if(bounds.intersection(clip).contains(mouse.getX(),mouse.getY()))
                        tooltips.add(new Tooltip("Optional: add up to "+count+" more.<br>You can leave out any approved item."));
                }
            }
        }finally{g.dispose();}
    }
    static void drawAddition(Graphics2D graphics,Rectangle bounds,int count){
        Graphics2D g=(Graphics2D)graphics.create();
        try{
            g.setColor(NEXT);g.setStroke(new BasicStroke(1.5f));g.drawRect(bounds.x,bounds.y,bounds.width-1,bounds.height-1);
            g.setFont(new Font(Font.SANS_SERIF,Font.BOLD,10));String text="+"+count;
            int width=g.getFontMetrics().stringWidth(text)+4,x=bounds.x+bounds.width-width,y=bounds.y+bounds.height-12;
            g.setColor(new Color(27,30,34));g.fillRect(x,y,width,12);g.setColor(RankedNhPanel.TEXT);g.drawString(text,x+2,y+10);
        }finally{g.dispose();}
    }
    private void guide(Graphics2D graphics,int group,String text,Color color){
        // Some native tabs are siblings of the frame rather than children of widget zero.
        for(int child=0;child<150;child++){
            Widget target=findText(visible(group,child),text,0);
            if(target==null)continue;
            Rectangle bounds=target.getBounds();
            if(bounds.width<=0 || bounds.height<=0)continue;
            Graphics2D g=(Graphics2D)graphics.create();
            try{g.setColor(color);g.setStroke(new BasicStroke(2));g.drawRoundRect(bounds.x-3,bounds.y-3,bounds.width+6,bounds.height+6,5,5);}
            finally{g.dispose();}
            return;
        }
    }
    private static void mark(Widget widget,ArenaKit.Change change,Map<Rectangle,ArenaKit.Change> slots){
        if(widget==null || widget.isHidden())return;Rectangle bounds=widget.getBounds();
        if(bounds.width>0 && bounds.height>0)slots.putIfAbsent(bounds,change);
    }
    static Widget findText(Widget root,String text,int depth){
        if(root==null || root.isHidden() || depth>8)return null;
        if(root.getText()!=null && text.equalsIgnoreCase(Text.removeTags(root.getText()).trim()))return root;
        for(Widget[] children:new Widget[][]{root.getDynamicChildren(),root.getStaticChildren()})if(children!=null)
            for(Widget child:children){Widget found=findText(child,text,depth+1);if(found!=null)return found;}
        return null;
    }
    static void drawBuildWarning(Graphics2D graphics,Rectangle target){
        Graphics2D g=(Graphics2D)graphics.create();
        try{
            g.setColor(WARNING);g.setStroke(new BasicStroke(2));g.drawRect(target.x-3,target.y-3,target.width+6,target.height+6);
            g.setFont(new Font(Font.SANS_SERIF,Font.BOLD,11));String text="Required: Max/Med";
            int width=g.getFontMetrics().stringWidth(text)+16,x=target.x+(target.width-width)/2,y=target.y+target.height+8;
            g.setColor(new Color(38,26,25));g.fillRect(x,y,width,21);g.setColor(WARNING);g.drawString(text,x+8,y+14);
        }finally{g.dispose();}
    }
    static void drawSlots(Graphics2D graphics,Iterable<Rectangle> slots){
        Graphics2D g=(Graphics2D)graphics.create();
        try{
            g.setColor(WARNING);g.setStroke(new BasicStroke(2));
            for(Rectangle r:slots){
                // A full red outline is easy to spot while leaving the item artwork unobscured.
                g.drawRect(r.x-1,r.y-1,r.width+2,r.height+2);
            }
        }finally{g.dispose();}
    }
    private Widget visible(int group,int child){Widget w=client.getWidget(group,child);return w==null || w.isHidden()?null:w;}
}

package com.rankednh;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Polygon;
import java.util.HashMap;
import java.util.Map;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.GameObject;
import net.runelite.api.GameState;
import net.runelite.api.Point;
import net.runelite.api.Perspective;
import net.runelite.api.Tile;
import net.runelite.api.coords.LocalPoint;
import net.runelite.client.ui.overlay.outline.ModelOutlineRenderer;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayUtil;

/** Points to the nearest supplies crate only while the first-time check needs it. */
final class ArenaSuppliesOverlay extends Overlay {
    static final Color GUIDE=RankedNhPanel.ACCENT;
    private final Client client;
    private final RankedNhPlugin plugin;
    private final ModelOutlineRenderer outlines;
    private final Map<Integer,Boolean> supplies=new HashMap<>();
    private GameObject crate;
    @Inject ArenaSuppliesOverlay(Client client,RankedNhPlugin plugin,ModelOutlineRenderer outlines){
        this.client=client;this.plugin=plugin;this.outlines=outlines;
        setPosition(OverlayPosition.DYNAMIC);setLayer(OverlayLayer.ABOVE_SCENE);setMovable(false);
    }
    void update(){
        crate=null;
        if(plugin.onboardingStep()!=ArenaOnboarding.Step.CRATE || client.getRevision()!=ArenaSetup.REVISION ||
            client.getGameState()!=GameState.LOGGED_IN || client.getLocalPlayer()==null)return;
        Tile[][] plane=client.getScene().getTiles()[client.getPlane()];int nearest=Integer.MAX_VALUE;
        for(Tile[] row:plane)for(Tile tile:row){
            if(tile==null)continue;
            for(GameObject object:tile.getGameObjects()){
                if(object==null || !supplies.computeIfAbsent(object.getId(),id->{
                    String name=client.getObjectDefinition(id).getName();
                    return "Supplies".equalsIgnoreCase(name) || "Supplies crate".equalsIgnoreCase(name);
                }))continue;
                int distance=object.getWorldLocation().distanceTo(client.getLocalPlayer().getWorldLocation());
                if(distance<nearest){nearest=distance;crate=object;}
            }
        }
    }
    @Override public Dimension render(Graphics2D graphics){
        if(crate==null || plugin.onboardingStep()!=ArenaOnboarding.Step.CRATE || client.getGameState()!=GameState.LOGGED_IN ||
            client.getLocalPlayer()==null)return null;
        Graphics2D g=(Graphics2D)graphics.create();
        try{
            g.clipRect(client.getViewportXOffset(),client.getViewportYOffset(),client.getViewportWidth(),client.getViewportHeight());
            outlines.drawOutline(crate,3,GUIDE,0);
            Polygon tile=crate.getCanvasTilePoly();
            if(tile!=null)OverlayUtil.renderPolygon(g,tile,GUIDE,new Color(236,4,4,28),new BasicStroke(2));
            LocalPoint[] ground=arrow(client.getLocalPlayer().getLocalLocation(),crate.getLocalLocation());
            Polygon arrow=new Polygon();
            for(LocalPoint vertex:ground){
                Point screen=Perspective.localToCanvas(client,vertex,client.getPlane(),0);
                if(screen==null){arrow=null;break;}
                arrow.addPoint(screen.getX(),screen.getY());
            }
            if(arrow!=null && arrow.npoints>=3)drawArrow(g,arrow);
            Point text=crate.getCanvasTextLocation(g,"Set up your kit",70);
            if(text!=null)OverlayUtil.renderTextLocation(g,text,"Set up your kit",RankedNhPanel.TEXT);
        }finally{g.dispose();}
        return null;
    }
    /** A short directional cue on the ground, not a walking route through scene obstacles. */
    static LocalPoint[] arrow(LocalPoint from,LocalPoint to){
        if(from==null || to==null || from.getWorldView()!=to.getWorldView())return new LocalPoint[0];
        double dx=to.getX()-from.getX(),dy=to.getY()-from.getY(),distance=Math.hypot(dx,dy);
        double start=80,length=Math.min(192,distance-start-96);
        if(length<64)return new LocalPoint[0];
        double ux=dx/distance,uy=dy/distance,neck=length-Math.min(64,length*.45);
        double[][] points={{0,-15},{neck,-15},{neck,-43},{length,0},{neck,43},{neck,15},{0,15}};
        LocalPoint[] polygon=new LocalPoint[points.length];
        for(int i=0;i<points.length;i++){
            double along=start+points[i][0],side=points[i][1];
            polygon[i]=from.plus((int)Math.round(ux*along-uy*side),(int)Math.round(uy*along+ux*side));
        }
        return polygon;
    }
    static void drawArrow(Graphics2D g,Polygon arrow){
        OverlayUtil.renderPolygon(g,arrow,new Color(65,20,23),new Color(236,4,4,220),new BasicStroke(2));
    }
}

package com.rankednh;

import java.util.concurrent.ScheduledExecutorService;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.game.WorldService;
import net.runelite.http.api.worlds.World;
import net.runelite.http.api.worlds.WorldRegion;
import net.runelite.http.api.worlds.WorldResult;
import net.runelite.http.api.worlds.WorldType;

/** Validates the suggested Arena world and opens the picker. The player selects the world. */
final class ArenaWorldGuide
{
    private final Client client;
    private final ClientThread clientThread;
    private final WorldService worlds;
    private final ScheduledExecutorService executor;
    private final RankedNhPlugin plugin;
    private volatile boolean busy;
    private long generation,started;
    private String matchId;
    private int round,world;
    private boolean readyToOpen;
    private volatile String instruction="",region="";
    private boolean setupHop;
    private String playerId;

    @Inject ArenaWorldGuide(Client client,ClientThread clientThread,WorldService worlds,ScheduledExecutorService executor,RankedNhPlugin plugin){
        this.client=client;this.clientThread=clientThread;this.worlds=worlds;this.executor=executor;this.plugin=plugin;
    }
    boolean busy(){return busy;}
    String instruction(){return instruction;}
    String region(){return region;}
    static boolean eligible(Models.Status s){return s!=null && s.match!=null && "preparing".equals(s.match.state) && !"demo".equals(s.mode);}
    static String validate(World destination,int assigned,String region){
        if(destination==null || destination.getId()!=assigned)return "Assigned world is unavailable. Refresh the world list and try again.";
        if(destination.getTypes()==null || !destination.getTypes().contains(WorldType.PVP_ARENA) || destination.getTypes().contains(WorldType.PVP) ||
            destination.getTypes().contains(WorldType.HIGH_RISK) || destination.getTypes().contains(WorldType.DEADMAN))
            return "Assigned world is not a safe Arena destination. Ask the operator to correct it.";
        WorldRegion country=destination.getRegion();
        String actual=country==WorldRegion.UNITED_STATES_OF_AMERICA?"US":
            country==WorldRegion.UNITED_KINGDOM || country==WorldRegion.GERMANY?"EU":country==WorldRegion.AUSTRALIA?"AU":"";
        if(!actual.equals(region))return "Assigned world does not match the competition region. Ask the operator to correct it.";
        if(destination.getPlayers()<0)return "Arena world is offline. Try again shortly.";
        if(destination.getPlayers()>=2000)return "Arena world is full. Try again shortly.";
        return null;
    }
    static World destination(WorldResult result,int assigned,String region){
        if(result==null || result.getWorlds()==null)return null;
        if(assigned>0)return result.findWorld(assigned);
        for(World candidate:result.getWorlds())if(validate(candidate,candidate.getId(),region)==null)return candidate;
        return null;
    }
    void request(){
        Models.Status s=plugin.status();
        if(busy)return;
        if(!plugin.accountMatches() || client.getGameState()!=GameState.LOGGED_IN){plugin.handoffProblem("Log into your enrolled account before opening the world switcher.");return;}
        if(!eligible(s)){plugin.handoffProblem(s!=null && "demo".equals(s.mode)?"Demo matches have no real Arena destination.":"Both players must accept before opening the world switcher.");return;}
        if(client.getWorld()==s.match.world)return;
        setupHop=false;matchId=s.match.id;round=s.match.round;
        start(s.match.world,s.match.region);
    }
    void requestSetup(String region){
        Models.Status s=plugin.status();
        if(busy)return;
        if(!plugin.accountMatches() || client.getGameState()!=GameState.LOGGED_IN || !ArenaOnboarding.idle(s) ||
            "demo".equals(s.mode) || plugin.inArenaBattle() || !("EU".equals(region) || "US".equals(region)))return;
        if(client.getWorldType().contains(net.runelite.api.WorldType.PVP_ARENA))return;
        setupHop=true;playerId=s.player.id;
        start(0,region);
    }
    private void start(int assigned,String region){
        busy=true;readyToOpen=false;world=assigned;instruction="";this.region=region;
        started=System.nanoTime();final long request=++generation;
        plugin.handoffProblem("");
        executor.execute(()->{
            World destination=null;
            try{
                destination=destination(worlds.getWorlds(),assigned,region);
            }
            catch(RuntimeException ignored){/* Surface a retryable error without blocking the game thread. */}
            final World resolved=destination;
            clientThread.invoke(()->{
                if(request!=generation || !busy)return;
                String error=assigned==0 && resolved==null?"Could not find an available "+region+" PvP Arena world. Refresh the world list and try again.":
                    validate(resolved,assigned>0?assigned:resolved.getId(),region);
                if(error!=null){worlds.refresh();fail(error);return;}
                if(!current()){cancel();return;}
                world=resolved.getId();
                instruction="Choose World "+world+" ("+region+") in the game’s world switcher.";
                readyToOpen=true;
            });
        });
    }
    private boolean current(){
        Models.Status s=plugin.status();
        if(setupHop)return ArenaOnboarding.idle(s) && plugin.accountMatches() && playerId.equals(s.player.id) && !plugin.inArenaBattle();
        return eligible(s) && plugin.accountMatches() && matchId.equals(s.match.id) && round==s.match.round && world==s.match.world && MatchFoundAlert.secondsLeft(s,plugin.serverNow())>0;
    }
    void tick(){
        if(!busy)return;
        if(System.nanoTime()-started>15_000_000_000L){fail("Could not load Arena worlds. Try again shortly.");return;}
        if(client.getGameState()==GameState.HOPPING || client.getGameState()==GameState.LOADING)return;
        if(!current() || client.getGameState()!=GameState.LOGGED_IN){cancel();return;}
        if(client.getWorld()==world){cancel();return;}
        if(!readyToOpen)return;
        // Opening the native picker does not select a world or perform a hop.
        client.openWorldHopper();
        busy=false;readyToOpen=false;
        plugin.handoffProblem("");
    }
    private void fail(String message){cancel();plugin.handoffProblem(message);}
    void cancel(){generation++;busy=false;readyToOpen=false;matchId=null;playerId=null;setupHop=false;instruction="";region="";}
}

package com.rankednh;

/** Checks arrival only. It never chooses gear, issues a challenge or starts combat. */
final class AutoReady
{
    private String key;
    private long arrivedAt=-1,nextAttempt;
    static String blocker(boolean nearby,int hitpoints){
        if(!nearby)return "Move into view of your opponent.";
        if(hitpoints<=0)return "Waiting for you to respawn.";
        return "";
    }
    boolean take(Models.Status s,boolean accountMatches,boolean busy,int world,boolean arena,
        boolean nearby,int hitpoints,long now,long serverNow){
        String current=s==null || s.match==null?null:s.player.id+":"+s.match.id+":"+s.match.round;
        if(current==null || !current.equals(key)){reset();key=current;}
        if(!accountMatches || s==null || s.match==null || !"pilot".equals(s.mode) ||
            !"preparing".equals(s.match.state) || s.match.ready || world!=s.match.world || !arena ||
            !blocker(nearby,hitpoints).isEmpty() || MatchFoundAlert.secondsLeft(s,serverNow)==0){
            arrivedAt=-1;return false;
        }
        if(arrivedAt<0)arrivedAt=now;
        // Let scene loading settle. A lost HTTP response can retry the idempotent endpoint.
        if(busy || now-arrivedAt<1200 || now<nextAttempt)return false;
        nextAttempt=now+5000;return true;
    }
    void reset(){key=null;arrivedAt=-1;nextAttempt=0;}
    boolean awaitingAcknowledgement(Models.Status s){return s!=null && s.player!=null && s.match!=null &&
        (s.player.id+":"+s.match.id+":"+s.match.round).equals(key) && nextAttempt>0 && !s.match.ready;}
}

package com.rankednh;

import java.awt.image.BufferedImage;
import java.util.HashMap;
import java.util.Map;
import javax.swing.ImageIcon;
import net.runelite.client.util.ImageUtil;

final class BadgeImages
{
    private static final Map<String,BufferedImage> CACHE=new HashMap<>();
    static synchronized BufferedImage image(String name) {
        String safe=name!=null && name.matches("[a-z_]+") ? name : "unranked";
        if(!CACHE.containsKey(safe)) {
            BufferedImage image=ImageUtil.loadImageResource(BadgeImages.class,"badges/"+safe+".png");
            CACHE.put(safe,image);
        }
        return CACHE.get(safe);
    }
    static ImageIcon icon(String name) { return new ImageIcon(image(name)); }
    static BufferedImage menuImage(String name){
        BufferedImage source=image(name);int left=source.getWidth(),top=source.getHeight(),right=-1,bottom=-1;
        for(int y=0;y<source.getHeight();y++)for(int x=0;x<source.getWidth();x++)if((source.getRGB(x,y)>>>24)>32){
            left=Math.min(left,x);top=Math.min(top,y);right=Math.max(right,x);bottom=Math.max(bottom,y);
        }
        if(right<left)return new BufferedImage(13,13,BufferedImage.TYPE_INT_ARGB);
        BufferedImage cropped=source.getSubimage(left,top,right-left+1,bottom-top+1);
        double scale=13.0/Math.max(cropped.getWidth(),cropped.getHeight());
        BufferedImage resized=ImageUtil.resizeImage(cropped,Math.max(1,(int)Math.round(cropped.getWidth()*scale)),Math.max(1,(int)Math.round(cropped.getHeight()*scale)));
        // Native indexed sprites only keep alpha 255. Resampling the Unranked
        // artwork produces alpha <=254 everywhere, making the whole icon vanish.
        BufferedImage menu=new BufferedImage(resized.getWidth(),resized.getHeight(),BufferedImage.TYPE_INT_ARGB);
        for(int y=0;y<resized.getHeight();y++)for(int x=0;x<resized.getWidth();x++){
            int argb=resized.getRGB(x,y);
            if((argb>>>24)<128)continue;
            int rgb=argb&0xffffff;
            // Palette entry zero is transparent in RuneLite's sprite converter.
            menu.setRGB(x,y,0xff000000|(rgb==0?1:rgb));
        }
        return menu;
    }
    private BadgeImages() {}
}

package com.rankednh;

import com.google.gson.Gson;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import javax.inject.Inject;
import javax.inject.Singleton;

/** Fixed reference bundled from shared/default-max-med.json, never learned from an opponent. */
@Singleton
final class DefaultArenaKit {
    private static final class Reference { String id; ArenaKit kit; }
    private final Reference reference;
    @Inject DefaultArenaKit(Gson gson){reference=load(gson);}
    private static Reference load(Gson gson){
        try(InputStreamReader reader=new InputStreamReader(DefaultArenaKit.class.getResourceAsStream("default-max-med.json"),StandardCharsets.UTF_8)){
            Reference reference=gson.fromJson(reader,Reference.class);
            if(reference.id==null || reference.kit==null || !reference.kit.complete() || reference.kit.revision!=ArenaSetup.REVISION)
                throw new IllegalStateException("Invalid Arena reference");
            return reference;
        }catch(java.io.IOException error){throw new IllegalStateException("Cannot read Arena reference",error);}
    }
    String id(){return reference.id;}
    ArenaKit kit(){return reference.kit;}
    boolean matches(ArenaKit kit){return kit!=null && kit.allowedBy(reference.kit);}
}

package com.rankednh;

import java.util.ArrayList;
import java.util.Locale;
import net.runelite.api.Actor;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Player;
import net.runelite.api.Skill;
import net.runelite.api.WorldType;

/** Client-thread only. Observes only the two enrolled participants during an armed Arena round. */
final class FightRecorder
{
    private Models.Status status;
    private String nonce;
    private final ArrayList<Models.Hit> hits=new ArrayList<>();
    private int startTick=-1, firstDeathTick=-1;
    private boolean selfDead,opponentDead,finished,interrupted;
    private String message="Waiting for a round";
    static String normalized(String name) {
        return name==null?"":name.replace('\u00a0',' ').replace('_',' ').trim().toLowerCase(Locale.ROOT);
    }
    void arm(Models.Status next) {
        Models.Match match=next.match;
        if(match==null || !("active".equals(match.state) || "reporting".equals(match.state))) { clear(); return; }
        if(match.nonce==null || match.nonce.equals(nonce)) return;
        clear();status=next;nonce=match.nonce;message="Ready to observe your manual Arena fight";
    }
    void clear() {
        status=null;nonce=null;hits.clear();startTick=-1;firstDeathTick=-1;
        selfDead=false;opponentDead=false;finished=false;interrupted=false;message="Waiting for a round";
    }
    private boolean context(Client client) {
        Player local=client.getLocalPlayer();
        return status!=null && !finished && !interrupted && client.getGameState()==GameState.LOGGED_IN &&
            local!=null && normalized(local.getName()).equals(normalized(status.player.rsn)) &&
            client.getWorld()==status.match.world && ArenaCombat.inBattle(client);
    }
    private String target(Actor actor) {
        if(!(actor instanceof Player) || status==null) return null;
        String name=normalized(actor.getName());
        if(name.equals(normalized(status.player.rsn))) return "self";
        if(name.equals(normalized(status.match.opponent.rsn))) return "opponent";
        return null;
    }
    void hit(Client client,Actor actor,int amount) {
        if(!context(client)) return;
        String target=target(actor);if(target==null) return;
        // Only begin while the assigned players are interacting. This is a pilot heuristic,
        // not a verified Arena result signal or protection against forged clients.
        if(startTick<0) {
            Actor interacting=client.getLocalPlayer().getInteracting();
            boolean opponentTargeted="opponent".equals(target(interacting));
            boolean opponentTargetsSelf="opponent".equals(target) && "self".equals(target(actor.getInteracting()));
            if(!opponentTargeted && !opponentTargetsSelf) return;
            // Arena applies build stats after the challenge, not on lobby arrival.
            if(client.getLocalPlayer().getCombatLevel()!=126 || !maxStats(client)){
                interrupted=true;message="Build mismatch — request a review";return;
            }
            startTick=client.getTickCount();
        }
        recordHit(target,amount,client.getTickCount());
    }
    static boolean maxStats(Client client){
        for(Skill skill:new Skill[]{Skill.ATTACK,Skill.STRENGTH,Skill.DEFENCE,Skill.HITPOINTS,Skill.RANGED,Skill.MAGIC,Skill.PRAYER})
            if(client.getRealSkillLevel(skill)!=99)return false;
        return true;
    }
    void recordHit(String target,int amount,int gameTick) {
        if(status==null || finished || interrupted || !("self".equals(target) || "opponent".equals(target)))return;
        if(startTick<0)startTick=gameTick;
        int tick=gameTick-startTick;
        if(tick>1500 || hits.size()>=3000) {interrupted=true;message="Recording limit reached — request a review";return;}
        if(amount<0 || amount>200) return;
        hits.add(new Models.Hit(target,amount,tick));message="Recording this round · "+hits.size()+" observations";
    }
    void death(Client client,Actor actor) {
        if(!context(client) || startTick<0) return;
        String target=target(actor);if(target==null) return;
        recordDeath(target,client.getTickCount());
    }
    void recordDeath(String target,int gameTick) {
        if(status==null || startTick<0 || finished || interrupted || !("self".equals(target) || "opponent".equals(target)))return;
        if("self".equals(target)) selfDead=true;else opponentDead=true;
        if(firstDeathTick<0) firstDeathTick=gameTick;
        message="Confirming observed round outcome";
    }
    void gameState(GameState state) {
        if(status!=null && !finished && (state==GameState.LOGIN_SCREEN || state==GameState.CONNECTION_LOST || state==GameState.HOPPING)) {
            interrupted=true;message="Recording interrupted — request a review";
        }
    }
    Models.Report tick(Client client) {
        if(!context(client))return null;
        return finishAt(client.getTickCount());
    }
    Models.Report finishAt(int gameTick) {
        if(status==null || finished || interrupted || firstDeathTick<0 || gameTick-firstDeathTick<3)return null;
        Models.Report result=new Models.Report();
        result.round=status.match.round;result.nonce=nonce;result.world=status.match.world;
        result.winner=selfDead?(opponentDead?null:status.match.opponent.id):status.player.id;
        result.endReason=selfDead && opponentDead?"double-death":"death";
        result.durationTicks=Math.max(1,gameTick-startTick);
        if(result.durationTicks>1500) {interrupted=true;message="Recording limit reached — request a review";return null;}
        result.hits=new ArrayList<>(hits);finished=true;message="Round report queued for submission";
        return result;
    }
    String message() { return message; }
    void stopForSetup(String reason){interrupted=true;message="Round not recorded: "+reason;}
    boolean started(){return startTick>=0;}
}

package com.rankednh;

import java.time.Instant;

/** A repeated poll, reconnect or world hop must not repeat the same matchup ping. */
final class MatchFoundAlert
{
    private String key;
    boolean take(Models.Status s,boolean accountMatches,long now){
        if(!accountMatches || s==null || s.player==null || s.match==null ||
            !"offered".equals(s.match.state) || s.match.accepted || secondsLeft(s,now)==0)return false;
        String next=s.player.id+":"+s.match.id;
        if(next.equals(key))return false;
        key=next;return true;
    }
    void reset(){key=null;}
    static int secondsLeft(Models.Status s,long serverNow){
        try{return (int)Math.max(0,Math.ceil((Instant.parse(s.match.deadline).toEpochMilli()-serverNow)/1000.0));}
        catch(Exception ignored){return 0;}
    }
    static String region(String region){
        return region==null?"Arena":"DEMO".equals(region)?"Local demo":region;
    }
}

