/** A bounded history drawer. Delayed responses cannot reopen a dismissed drawer. */
final class MatchHistoryPanel extends JPanel {
    private final JPanel content=new JPanel();
    private final Runnable retry;
    private long request;
    MatchHistoryPanel(Runnable closed,Runnable retry){
        this.retry=retry;setLayout(new BorderLayout(0,8));setBackground(RankedNhPanel.BG);
        setAlignmentX(LEFT_ALIGNMENT);setBorder(BorderFactory.createEmptyBorder(8,0,0,0));
        JPanel heading=new JPanel(new BorderLayout());heading.setOpaque(false);
        heading.add(label("Recent matches",11,RankedNhPanel.MUTED),BorderLayout.WEST);
        JButton close=control("Close",()->{close();closed.run();});
        close.getAccessibleContext().setAccessibleName("Close match history");heading.add(close,BorderLayout.EAST);add(heading,BorderLayout.NORTH);
        content.setLayout(new BoxLayout(content,BoxLayout.Y_AXIS));content.setOpaque(false);add(content,BorderLayout.CENTER);
        setVisible(false);
    }
    @Override public Dimension getMaximumSize(){return new Dimension(Integer.MAX_VALUE,getPreferredSize().height);}
    long request(){return request;}
    void open(){request++;setVisible(true);message("Loading matches…",false);}
    void close(){request++;setVisible(false);content.removeAll();revalidate();repaint();}
    void failed(long id){if(id==request && isVisible())message("Couldn't load matches.",true);}
    void show(long id,String playerId,List<Models.Match> matches){
        if(id!=request || !isVisible())return;
        if(matches.isEmpty()){message("No matches yet.",false);return;}
        content.removeAll();
        JPanel rows=new JPanel();rows.setLayout(new BoxLayout(rows,BoxLayout.Y_AXIS));rows.setBackground(RankedNhPanel.SURFACE);
        for(Models.Match match:matches)rows.add(row(match,playerId));
        JScrollPane scroll=new JScrollPane(rows,JScrollPane.VERTICAL_SCROLLBAR_AS_NEEDED,JScrollPane.HORIZONTAL_SCROLLBAR_NEVER);
        scroll.setBorder(BorderFactory.createLineBorder(RankedNhPanel.LINE));scroll.getViewport().setBackground(RankedNhPanel.SURFACE);
        scroll.setPreferredSize(new Dimension(1,Math.min(4,matches.size())*64+2));scroll.getVerticalScrollBar().setUnitIncrement(32);
        scroll.getAccessibleContext().setAccessibleName("Recent matches, newest first");content.add(scroll);revalidate();repaint();
    }
    private void message(String text,boolean error){
        content.removeAll();content.add(label(text,11,error?new Color(231,156,147):RankedNhPanel.MUTED));
        if(error){content.add(Box.createVerticalStrut(8));content.add(control("Try again",()->{open();retry.run();}));}
        revalidate();repaint();
    }
    private JPanel row(Models.Match match,String playerId){
        JPanel row=new JPanel(new BorderLayout(0,6));row.setOpaque(false);
        row.setBorder(BorderFactory.createCompoundBorder(BorderFactory.createMatteBorder(0,0,1,0,RankedNhPanel.LINE),BorderFactory.createEmptyBorder(8,8,8,8)));
        row.setPreferredSize(new Dimension(1,64));row.setMaximumSize(new Dimension(Integer.MAX_VALUE,64));
        Color resultColor="Won".equals(outcome(match,playerId))?RankedNhPanel.SUCCESS:"Lost".equals(outcome(match,playerId))?new Color(231,156,147):RankedNhPanel.MUTED;
        JPanel top=new JPanel(new BorderLayout(4,0));top.setOpaque(false);
        JLabel name=label(match.opponent==null?"Opponent":match.opponent.rsn,12,RankedNhPanel.TEXT);
        if(match.opponent!=null && match.opponent.rank!=null){
            name.setIcon(new ImageIcon(ImageUtil.resizeImage(BadgeImages.image(match.opponent.rank.badge),18,18)));name.setIconTextGap(4);
            name.setToolTipText("Current rank: "+match.opponent.rank.name);
        }
        top.add(name,BorderLayout.CENTER);
        String score="void".equals(match.state) || match.score==null || match.score.length<2?"—":match.score[0]+"–"+match.score[1];
        JLabel scoreLabel=label(score,13,resultColor);scoreLabel.getAccessibleContext().setAccessibleName("Your score first: "+score);
        top.add(scoreLabel,BorderLayout.EAST);row.add(top,BorderLayout.NORTH);
        JPanel bottom=new JPanel(new BorderLayout(4,0));bottom.setOpaque(false);
        String result=outcome(match,playerId);
        if("complete".equals(match.state))result+=!match.rated?" · Unrated":match.ratingChange==null?"":" · "+(match.ratingChange>=0?"+":"")+match.ratingChange;
        bottom.add(label(result,10,resultColor),BorderLayout.WEST);
        bottom.add(label(date(match,ZoneId.systemDefault()),10,RankedNhPanel.MUTED),BorderLayout.EAST);
        row.add(bottom,BorderLayout.SOUTH);
        if(match.reason!=null)row.setToolTipText(match.reason);
        return row;
    }
    static String outcome(Models.Match match,String playerId){
        if("complete".equals(match.state))return match.winner==null || playerId==null?"Complete":playerId.equals(match.winner)?"Won":"Lost";
        if("void".equals(match.state))return "Cancelled";
        if("review".equals(match.state))return "Under review";
        return "In progress";
    }
    static String date(Models.Match match,ZoneId zone){
        try{return Instant.parse(match.endedAt==null?match.createdAt:match.endedAt).atZone(zone).format(DateTimeFormatter.ofPattern("d MMM · HH:mm",Locale.UK));}
        catch(RuntimeException invalid){return "";}
    }
    private static JLabel label(String text,int size,Color color){
        JLabel label=new JLabel(text);label.setFont(new Font(Font.SANS_SERIF,Font.PLAIN,size));label.setForeground(color);label.setAlignmentX(LEFT_ALIGNMENT);return label;
    }
    private static JButton control(String text,Runnable action){
        JButton button=new JButton(text);button.setFont(new Font(Font.SANS_SERIF,Font.PLAIN,11));button.setFocusPainted(false);
        button.setAlignmentX(LEFT_ALIGNMENT);button.addActionListener(e->action.run());
        Runnable style=()->{
            button.setBackground(button.getModel().isPressed()?RankedNhPanel.BG:button.getModel().isRollover()?RankedNhPanel.LINE:RankedNhPanel.SURFACE);
            button.setForeground(RankedNhPanel.TEXT);button.setBorder(BorderFactory.createCompoundBorder(BorderFactory.createLineBorder(button.hasFocus()?RankedNhPanel.ACCENT:RankedNhPanel.LINE),BorderFactory.createEmptyBorder(4,8,4,8)));
        };
        button.getModel().addChangeListener(e->style.run());button.addFocusListener(new java.awt.event.FocusAdapter(){
            @Override public void focusGained(java.awt.event.FocusEvent e){style.run();}
            @Override public void focusLost(java.awt.event.FocusEvent e){style.run();}
        });style.run();return button;
    }
}

package com.rankednh;

/** A monotonic clock: network polling never restarts an already visible result. */
final class MatchReportAnimation
{
    static final long ENTRANCE_MS=220,DELAY_MS=300,RATING_MS=1500;
    static final long SPIN_MS=1100;
    static final long PROMOTION_FILL_END=1100,PROMOTION_REVEAL_START=1100,PROMOTION_REVEAL_END=1260,
        PROMOTION_SPIN_END=PROMOTION_REVEAL_END+SPIN_MS,PROMOTION_END=PROMOTION_SPIN_END+800;
    static final long PLACEMENT_FADE_START=480,PLACEMENT_REVEAL=700,PLACEMENT_BADGE_END=PLACEMENT_REVEAL+SPIN_MS,
        PLACEMENT_NAME_START=PLACEMENT_BADGE_END-40,PLACEMENT_RATING_START=PLACEMENT_BADGE_END+160,PLACEMENT_END=PLACEMENT_BADGE_END+380;
    private String key;
    private long started;

    Frame frame(String reportKey,MatchReportView view,long now,boolean reducedMotion) {
        if(!reportKey.equals(key)){key=reportKey;started=now;}
        return sample(view,Math.max(0,now-started),reducedMotion);
    }
    void reset(){key=null;}

    static Frame sample(MatchReportView view,long elapsed,boolean reducedMotion) {
        Frame frame=sampleFrame(view,elapsed,reducedMotion);frame.elapsed=elapsed;return frame;
    }
    private static Frame sampleFrame(MatchReportView view,long elapsed,boolean reducedMotion) {
        if(view.placementReveal)return placement(view,elapsed,reducedMotion);
        if(view.promotion())return promotion(view,elapsed,reducedMotion);
        double entrance=reducedMotion?1:ease(elapsed/(double)ENTRANCE_MS);
        double t=reducedMotion?1:ease((elapsed-DELAY_MS)/(double)RATING_MS);
        Integer rating=null;
        double progress=view.progress;
        String label=view.progressLabel,detail=view.progressDetail;
        String badge=view.badge,rank=view.rank,title=view.title;
        if(view.ratingBefore!=null && view.ratingAfter!=null) {
            double interpolated=view.ratingBefore+(view.ratingAfter-view.ratingBefore)*t;
            rating=(int)Math.round(interpolated);
            boolean beforePromotion=view.badgeBefore!=null && view.previousDivisionStart!=null && view.divisionStart!=null && interpolated<view.divisionStart;
            // The badge and track describe the confirmed final division. Crossing into it
            // starts at zero; a demotion enters it from a full bar. Never infer a rank locally.
            if(view.divisionStart!=null && view.nextAt!=null && view.nextAt>view.divisionStart) {
                progress=clamp((interpolated-view.divisionStart)/(double)(view.nextAt-view.divisionStart));
                label=Math.max(0,view.nextAt-rating)+" rating to "+(view.nextRank==null?"next division":view.nextRank);
                detail=rating+" / "+view.nextAt+" rating";
            }
            if(beforePromotion){
                badge=view.badgeBefore;rank=view.rankBefore;
                progress=clamp((interpolated-view.previousDivisionStart)/(view.divisionStart-(double)view.previousDivisionStart));
                label=Math.max(0,view.divisionStart-rating)+" rating to "+view.rank;detail=rating+" / "+view.divisionStart+" rating";
            }else if(view.previousDivisionStart!=null)title="Rank up";
            if(view.badgeBefore!=null && view.previousDivisionStart==null && t<0.5){badge=view.badgeBefore;rank=view.rankBefore;}
        }
        return new Frame(entrance,rating,progress,label,detail,badge,rank,title);
    }
    private static Frame placement(MatchReportView view,long elapsed,boolean reducedMotion){
        boolean revealed=reducedMotion || elapsed>=PLACEMENT_REVEAL;
        Frame frame=new Frame(reducedMotion?1:ease(elapsed/(double)ENTRANCE_MS),
            revealed?view.ratingAfter:null,0,"","",revealed?view.badge:"unranked",revealed?view.rank:"","Placements complete");
        frame.reveal=reducedMotion?1:clamp((elapsed-PLACEMENT_REVEAL)/(double)(PLACEMENT_BADGE_END-PLACEMENT_REVEAL));
        frame.spin=revealed && !reducedMotion?frame.reveal:-1;
        frame.badgeAlpha=reducedMotion?1:revealed?ease((elapsed-PLACEMENT_REVEAL)/100.0):1-ease((elapsed-PLACEMENT_FADE_START)/(double)(PLACEMENT_REVEAL-PLACEMENT_FADE_START));
        frame.badgeScale=revealed?.96+.04*ease(frame.reveal):1;
        frame.stillMix=reducedMotion?1:ease((elapsed-PLACEMENT_BADGE_END)/160.0);
        frame.rankAlpha=reducedMotion?1:ease((elapsed-PLACEMENT_NAME_START)/200.0);
        frame.ratingAlpha=reducedMotion?1:ease((elapsed-PLACEMENT_RATING_START)/(double)(PLACEMENT_END-PLACEMENT_RATING_START));
        return frame;
    }
    private static Frame promotion(MatchReportView view,long elapsed,boolean reducedMotion){
        double reveal=reducedMotion?1:clamp((elapsed-PROMOTION_REVEAL_START)/(double)(PROMOTION_REVEAL_END-PROMOTION_REVEAL_START));
        boolean promoted=reducedMotion || elapsed>=PROMOTION_REVEAL_END;
        double rating;
        if(reducedMotion)rating=view.ratingAfter;
        else if(elapsed<PROMOTION_FILL_END)rating=view.ratingBefore+(view.divisionStart-view.ratingBefore)*ease((elapsed-DELAY_MS)/(double)(PROMOTION_FILL_END-DELAY_MS));
        else rating=view.divisionStart+(view.ratingAfter-view.divisionStart)*ease((elapsed-PROMOTION_SPIN_END)/(double)(PROMOTION_END-PROMOTION_SPIN_END));
        int displayed=(int)Math.floor(rating+1e-7);
        double progress=promoted?(view.nextAt==null?1:clamp((rating-view.divisionStart)/(view.nextAt-(double)view.divisionStart))):
            clamp((rating-view.previousDivisionStart)/(view.divisionStart-(double)view.previousDivisionStart));
        String label=promoted?(view.nextAt==null?"Highest division reached":Math.max(0,view.nextAt-displayed)+" rating to "+view.nextRank):
            displayed>=view.divisionStart?"New rank unlocked":(view.divisionStart-displayed)+" rating to "+view.rank;
        Frame frame=new Frame(reducedMotion?1:ease(elapsed/(double)ENTRANCE_MS),displayed,progress,label,
            displayed+" / "+(promoted?view.nextAt:view.divisionStart)+" rating",promoted?view.badge:view.badgeBefore,
            promoted?view.rank:view.rankBefore,promoted?"Rank up":view.title);
        frame.reveal=reveal;frame.promoted=promoted;
        frame.spin=promoted && !reducedMotion?clamp((elapsed-PROMOTION_REVEAL_END)/(double)SPIN_MS):-1;
        frame.badgeAlpha=reducedMotion?1:promoted?ease((elapsed-PROMOTION_REVEAL_END)/100.0):1-ease(reveal);
        frame.badgeScale=promoted?.96+.04*ease(frame.spin<0?1:frame.spin):1;
        frame.stillMix=reducedMotion?1:ease((elapsed-PROMOTION_SPIN_END)/160.0);
        frame.rankAlpha=reducedMotion?1:promoted?ease((elapsed-PROMOTION_SPIN_END+40)/200.0):1-ease(reveal);
        frame.ratingAlpha=reducedMotion?1:promoted?ease((elapsed-PROMOTION_SPIN_END)/200.0):1-ease(reveal);
        return frame;
    }
    private static double clamp(double n){return Math.max(0,Math.min(1,n));}
    private static double ease(double n){double t=clamp(n);return 1-Math.pow(1-t,3);}

    static final class Frame {
        final double entrance,progress;
        final Integer rating;
        final String progressLabel,progressDetail;
        final String badge,rank,title;
        double reveal=1;
        double badgeAlpha=1,badgeScale=1,rankAlpha=1,ratingAlpha=1;
        double spin=-1,stillMix=1;
        long elapsed;
        boolean promoted;
        Frame(double entrance,Integer rating,double progress,String label,String detail,String badge,String rank,String title){
            this.entrance=entrance;this.rating=rating;this.progress=progress;progressLabel=label;progressDetail=detail;
            this.badge=badge;this.rank=rank;this.title=title;
        }
    }
}

package com.rankednh;

import java.awt.Point;
import java.awt.event.KeyEvent;
import java.awt.event.MouseEvent;
import java.awt.event.MouseWheelEvent;
import java.util.HashSet;
import java.util.Set;
import net.runelite.client.input.KeyListener;
import net.runelite.client.input.MouseAdapter;
import net.runelite.client.input.MouseWheelListener;

/** The card captures its controls. An outside click dismisses without clicking the game. */
final class MatchReportInput extends MouseAdapter implements KeyListener,MouseWheelListener
{
    private final Runnable dismiss;
    private volatile MatchReportLayout layout;
    private volatile Point pointer=new Point(-1,-1);
    private volatile int focused,armed;
    private final Set<Integer> mouseDown=new HashSet<>(),swallowClick=new HashSet<>(),keysDown=new HashSet<>();
    private boolean swallowTyped;

    MatchReportInput(Runnable dismiss){this.dismiss=dismiss;}
    void show(MatchReportLayout next){layout=next;}
    void hide(){layout=null;focused=0;}
    boolean visible(){return layout!=null;}
    int hovered(){MatchReportLayout current=layout;return current==null?0:current.control(pointer);}
    int focused(){return focused;}
    int pressed(){return armed;}
    private boolean inside(Point point){MatchReportLayout current=layout;return current!=null && current.contains(point);}
    private void close(){hide();dismiss.run();}

    @Override public synchronized MouseEvent mousePressed(MouseEvent e){
        pointer=e.getPoint();swallowClick.remove(e.getButton());
        if(inside(pointer)){
            mouseDown.add(e.getButton());e.consume();
            if(e.getButton()==MouseEvent.BUTTON1){armed=hovered();focused=0;}
        }else if(visible()){
            mouseDown.add(e.getButton());e.consume();close();
        }
        return e;
    }
    @Override public synchronized MouseEvent mouseReleased(MouseEvent e){
        pointer=e.getPoint();boolean captured=mouseDown.remove(e.getButton());
        if(captured || inside(pointer)){e.consume();swallowClick.add(e.getButton());}
        if(e.getButton()==MouseEvent.BUTTON1){
            int control=armed;armed=0;
            if(captured && control!=0 && control==hovered())close();
        }
        return e;
    }
    @Override public synchronized MouseEvent mouseClicked(MouseEvent e){
        if(swallowClick.remove(e.getButton()) || inside(e.getPoint()))e.consume();return e;
    }
    @Override public synchronized MouseEvent mouseDragged(MouseEvent e){
        pointer=e.getPoint();if(!mouseDown.isEmpty() || inside(pointer))e.consume();return e;
    }
    @Override public MouseEvent mouseMoved(MouseEvent e){pointer=e.getPoint();if(inside(pointer))e.consume();return e;}
    @Override public MouseEvent mouseExited(MouseEvent e){pointer=new Point(-1,-1);return e;}
    @Override public MouseWheelEvent mouseWheelMoved(MouseWheelEvent e){if(inside(e.getPoint()))e.consume();return e;}

    @Override public synchronized void keyPressed(KeyEvent e){
        int code=e.getKeyCode();
        boolean control=code==KeyEvent.VK_ESCAPE || code==KeyEvent.VK_ENTER || code==KeyEvent.VK_TAB || (code==KeyEvent.VK_SPACE && focused!=0);
        if(visible() && control || keysDown.contains(code)){
            boolean first=keysDown.add(code);swallowTyped=true;e.consume();
            if(first && visible()){
                if(code==KeyEvent.VK_ESCAPE || code==KeyEvent.VK_ENTER || (code==KeyEvent.VK_SPACE && focused!=0))close();
                else if(code==KeyEvent.VK_TAB)focused=focused==2?1:2;
            }
        }
    }
    @Override public synchronized void keyReleased(KeyEvent e){
        if(keysDown.remove(e.getKeyCode()))e.consume();
        if(keysDown.isEmpty())swallowTyped=false;
    }
    @Override public synchronized void keyTyped(KeyEvent e){if(swallowTyped){e.consume();swallowTyped=false;}}
    @Override public synchronized void focusLost(){keysDown.clear();mouseDown.clear();swallowClick.clear();swallowTyped=false;armed=0;}
}

package com.rankednh;

import java.awt.Point;
import java.awt.Rectangle;
import java.awt.geom.Point2D;

/** The renderer and input handler share exactly the same canvas coordinates. */
final class MatchReportLayout
{
    static final int WIDTH=440,HEIGHT=324;
    static final Rectangle CLOSE=new Rectangle(396,6,36,36),CONTINUE=new Rectangle(272,278,144,30);
    final Rectangle canvas;
    final double scale,x,y;

    MatchReportLayout(int width,int height,double entrance) {
        this(new Rectangle(0,0,width,height),entrance);
    }
    MatchReportLayout(Rectangle viewport,double entrance){
        canvas=new Rectangle(viewport);
        scale=Math.max(0.01,Math.min(1,Math.min((viewport.width-40)/(double)WIDTH,(viewport.height-40)/(double)HEIGHT)));
        x=viewport.x+(viewport.width-WIDTH*scale)/2;
        y=viewport.y+(viewport.height-HEIGHT*scale)/2+8*scale*(1-entrance);
    }
    boolean contains(Point point){Point2D p=local(point);return p.getX()>=0 && p.getY()>=0 && p.getX()<WIDTH && p.getY()<HEIGHT;}
    Point2D local(Point point){return new Point2D.Double((point.x-x)/scale,(point.y-y)/scale);}
    int control(Point point){
        Point2D local=local(point);
        return CLOSE.contains(local)?1:CONTINUE.contains(local)?2:0;
    }
}

package com.rankednh;

import java.awt.AlphaComposite;
