package com.rankednh;

import java.awt.Component;
import java.awt.Container;
import java.time.ZoneId;
import java.util.List;
import java.util.concurrent.atomic.AtomicInteger;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JScrollPane;
import javax.swing.SwingUtilities;
import org.junit.Test;
import static org.junit.Assert.*;

public class MatchHistoryTest {
    static Models.Match match(String state,String winner){
        Models.Match match=new Models.Match();match.state=state;match.winner=winner;match.score=new int[]{2,0};
        match.createdAt="2026-10-12T23:50:00Z";match.endedAt="2026-10-13T00:12:00Z";
        match.opponent=new Models.Opponent();match.opponent.rsn="Other Main";
        match.opponent.rank=new Models.Rank();match.opponent.rank.name="Ruby II";match.opponent.rank.badge="ruby_ii";
        return match;
    }
    @Test public void resultsUseYourPerspectiveAndDatesUseLocalTime(){
        assertEquals("Won",MatchHistoryPanel.outcome(match("complete","me"),"me"));
        assertEquals("Lost",MatchHistoryPanel.outcome(match("complete","them"),"me"));
        assertEquals("Cancelled",MatchHistoryPanel.outcome(match("void",null),"me"));
        assertEquals("Under review",MatchHistoryPanel.outcome(match("review",null),"me"));
        Models.Match match=match("complete","me");
        assertEquals("13 Oct · 01:12",MatchHistoryPanel.date(match,ZoneId.of("Europe/London")));
        assertEquals("12 Oct · 17:12",MatchHistoryPanel.date(match,ZoneId.of("America/Los_Angeles")));
        match.endedAt=null;assertEquals("13 Oct · 00:50",MatchHistoryPanel.date(match,ZoneId.of("Europe/London")));
        match.createdAt=null;assertEquals("",MatchHistoryPanel.date(match,ZoneId.of("Europe/London")));
    }
    @Test public void closingDuringLoadingRejectsOldSuccessAndFailureEvenAfterReopening()throws Exception{
        SwingUtilities.invokeAndWait(()->{
            AtomicInteger closed=new AtomicInteger();MatchHistoryPanel history=new MatchHistoryPanel(closed::incrementAndGet,()->{});
            history.open();long first=history.request();button(history,"Close").doClick();assertFalse(history.isVisible());assertEquals(1,closed.get());
            history.show(first,"me",List.of(match("complete","me")));assertFalse(history.isVisible());
            history.open();history.show(first,"me",List.of(match("complete","me")));history.failed(first);
            assertTrue(hasLabel(history,"Loading matches…"));
            history.show(history.request(),"me",List.of(match("complete","me")));assertTrue(hasLabel(history,"Won · Unrated"));
        });
    }
    @Test public void emptyErrorRetryAndLongHistoryKeepACloseControl()throws Exception{
        SwingUtilities.invokeAndWait(()->{
            AtomicInteger retried=new AtomicInteger();MatchHistoryPanel history=new MatchHistoryPanel(()->{},retried::incrementAndGet);
            history.open();history.show(history.request(),"me",List.of());assertTrue(hasLabel(history,"No matches yet."));
            history.failed(history.request());assertTrue(hasLabel(history,"Couldn't load matches."));
            long failed=history.request();button(history,"Try again").doClick();assertEquals(1,retried.get());assertTrue(history.request()>failed);
            history.show(history.request(),"me",java.util.Collections.nCopies(20,match("complete","me")));
            JScrollPane scroll=find(history,JScrollPane.class);assertNotNull(scroll);assertTrue(scroll.getPreferredSize().height<=260);
            assertNotNull(button(history,"Close"));
        });
    }
    private static JButton button(Container c,String text){
        for(Component child:c.getComponents()){
            if(child instanceof JButton && text.equals(((JButton)child).getText()))return (JButton)child;
            if(child instanceof Container){JButton found=button((Container)child,text);if(found!=null)return found;}
        }return null;
    }
    private static boolean hasLabel(Container c,String text){
        for(Component child:c.getComponents()){
            if(child instanceof JLabel && text.equals(((JLabel)child).getText()))return true;
            if(child instanceof Container && hasLabel((Container)child,text))return true;
        }return false;
    }
    private static <T> T find(Container c,Class<T> type){
        for(Component child:c.getComponents()){
            if(type.isInstance(child))return type.cast(child);
            if(child instanceof Container){T found=find((Container)child,type);if(found!=null)return found;}
        }return null;
    }
}

package com.rankednh;

import java.awt.Canvas;
import java.awt.Point;
import java.awt.event.KeyEvent;
import java.awt.event.MouseEvent;
import java.awt.event.MouseWheelEvent;
import java.util.concurrent.atomic.AtomicInteger;
import org.junit.Test;
import static org.junit.Assert.*;

public class MatchReportInputTest
{
    private final Canvas canvas=new Canvas();
    private MouseEvent mouse(int type,Point p){return new MouseEvent(canvas,type,0,0,p.x,p.y,1,false,MouseEvent.BUTTON1);}
    private KeyEvent key(int type,int code,char value){return new KeyEvent(canvas,type,0,0,code,value);}
    private Point at(MatchReportLayout layout,int x,int y){return new Point((int)(layout.x+x*layout.scale),(int)(layout.y+y*layout.scale));}

    @Test public void closeAndContinueWorkAtFixedAndResizableSizesWithoutClickThrough(){
        for(int[] size:new int[][]{{765,503},{1024,768},{1920,1080}}){
            for(int[] control:new int[][]{{414,24},{344,293}}){
                AtomicInteger closes=new AtomicInteger();MatchReportInput input=new MatchReportInput(closes::incrementAndGet);
                MatchReportLayout layout=new MatchReportLayout(size[0],size[1],1);input.show(layout);
                assertTrue(layout.x>=0 && layout.y>=0);
                assertTrue(layout.x+MatchReportLayout.WIDTH*layout.scale<=size[0]);
                assertTrue(layout.y+MatchReportLayout.HEIGHT*layout.scale<=size[1]);
                Point p=at(layout,control[0],control[1]);
                assertTrue(input.mousePressed(mouse(MouseEvent.MOUSE_PRESSED,p)).isConsumed());assertEquals(0,closes.get());
                assertTrue(input.mouseReleased(mouse(MouseEvent.MOUSE_RELEASED,p)).isConsumed());assertEquals(1,closes.get());
                assertFalse(input.visible());assertTrue(input.mouseClicked(mouse(MouseEvent.MOUSE_CLICKED,p)).isConsumed());
                assertFalse(input.mousePressed(mouse(MouseEvent.MOUSE_PRESSED,new Point(2,2))).isConsumed());
            }
        }
    }
    @Test public void draggingOutDoesNotActivateAControlAndOutsideClickDismissesWithoutClickThrough(){
        AtomicInteger closes=new AtomicInteger();MatchReportInput input=new MatchReportInput(closes::incrementAndGet);
        MatchReportLayout layout=new MatchReportLayout(1024,768,1);input.show(layout);
        Point outside=new Point(2,2),close=at(layout,414,24);
        input.mousePressed(mouse(MouseEvent.MOUSE_PRESSED,close));
        assertTrue(input.mouseDragged(mouse(MouseEvent.MOUSE_DRAGGED,outside)).isConsumed());
        assertTrue(input.mouseReleased(mouse(MouseEvent.MOUSE_RELEASED,outside)).isConsumed());
        assertTrue(input.mouseClicked(mouse(MouseEvent.MOUSE_CLICKED,outside)).isConsumed());
        assertEquals(0,closes.get());assertTrue(input.visible());
        assertTrue(input.mousePressed(mouse(MouseEvent.MOUSE_PRESSED,outside)).isConsumed());
        assertTrue(input.mouseReleased(mouse(MouseEvent.MOUSE_RELEASED,outside)).isConsumed());
        assertTrue(input.mouseClicked(mouse(MouseEvent.MOUSE_CLICKED,outside)).isConsumed());
        assertEquals(1,closes.get());assertFalse(input.visible());
    }
    @Test public void escapeConsumesPressRepeatTypedAndReleaseThenRestoresInput(){
        AtomicInteger closes=new AtomicInteger();MatchReportInput input=new MatchReportInput(closes::incrementAndGet);
        input.show(new MatchReportLayout(765,503,1));
        KeyEvent press=key(KeyEvent.KEY_PRESSED,KeyEvent.VK_ESCAPE,(char)27);input.keyPressed(press);
        assertTrue(press.isConsumed());assertEquals(1,closes.get());assertFalse(input.visible());
        KeyEvent repeat=key(KeyEvent.KEY_PRESSED,KeyEvent.VK_ESCAPE,(char)27);input.keyPressed(repeat);
        assertTrue(repeat.isConsumed());assertEquals(1,closes.get());
        KeyEvent typed=key(KeyEvent.KEY_TYPED,KeyEvent.VK_UNDEFINED,(char)27);input.keyTyped(typed);assertTrue(typed.isConsumed());
        KeyEvent release=key(KeyEvent.KEY_RELEASED,KeyEvent.VK_ESCAPE,(char)27);input.keyReleased(release);assertTrue(release.isConsumed());
        KeyEvent next=key(KeyEvent.KEY_PRESSED,KeyEvent.VK_ESCAPE,(char)27);input.keyPressed(next);assertFalse(next.isConsumed());
    }
    @Test public void hidingMidGestureStillConsumesItsReleaseAndClick(){
        MatchReportInput input=new MatchReportInput(()->{});MatchReportLayout layout=new MatchReportLayout(765,503,1);input.show(layout);Point p=at(layout,100,100);
        input.mousePressed(mouse(MouseEvent.MOUSE_PRESSED,p));input.hide();
        assertTrue(input.mouseReleased(mouse(MouseEvent.MOUSE_RELEASED,p)).isConsumed());
        assertTrue(input.mouseClicked(mouse(MouseEvent.MOUSE_CLICKED,p)).isConsumed());
    }
    @Test public void keyboardFocusAndEnterCanDismissWithoutAMouse(){
        AtomicInteger closes=new AtomicInteger();MatchReportInput input=new MatchReportInput(closes::incrementAndGet);
        input.show(new MatchReportLayout(765,503,1));
        input.keyPressed(key(KeyEvent.KEY_PRESSED,KeyEvent.VK_TAB,'\t'));assertEquals(2,input.focused());
        input.keyReleased(key(KeyEvent.KEY_RELEASED,KeyEvent.VK_TAB,'\t'));
        input.keyPressed(key(KeyEvent.KEY_PRESSED,KeyEvent.VK_TAB,'\t'));assertEquals(1,input.focused());
        input.keyPressed(key(KeyEvent.KEY_PRESSED,KeyEvent.VK_ENTER,'\n'));assertEquals(1,closes.get());
    }
    @Test public void wheelOnlyBlocksInsideTheVisibleCardAndNormalTypingPassesThrough(){
        MatchReportInput input=new MatchReportInput(()->{});MatchReportLayout layout=new MatchReportLayout(765,503,1);input.show(layout);
        Point p=at(layout,100,100);
        MouseWheelEvent wheel=new MouseWheelEvent(canvas,MouseEvent.MOUSE_WHEEL,0,0,p.x,p.y,0,false,MouseWheelEvent.WHEEL_UNIT_SCROLL,1,1);
        assertTrue(input.mouseWheelMoved(wheel).isConsumed());
        wheel=new MouseWheelEvent(canvas,MouseEvent.MOUSE_WHEEL,0,0,10,10,0,false,MouseWheelEvent.WHEEL_UNIT_SCROLL,1,1);
        assertFalse(input.mouseWheelMoved(wheel).isConsumed());
        KeyEvent letter=key(KeyEvent.KEY_PRESSED,KeyEvent.VK_A,'a');input.keyPressed(letter);assertFalse(letter.isConsumed());
        KeyEvent typed=key(KeyEvent.KEY_TYPED,KeyEvent.VK_UNDEFINED,'a');input.keyTyped(typed);assertFalse(typed.isConsumed());
        wheel=new MouseWheelEvent(canvas,MouseEvent.MOUSE_WHEEL,0,0,p.x,p.y,0,false,MouseWheelEvent.WHEEL_UNIT_SCROLL,1,1);
        assertTrue(input.mouseWheelMoved(wheel).isConsumed());input.hide();
        wheel=new MouseWheelEvent(canvas,MouseEvent.MOUSE_WHEEL,0,0,10,10,0,false,MouseWheelEvent.WHEEL_UNIT_SCROLL,1,1);
        assertFalse(input.mouseWheelMoved(wheel).isConsumed());
    }
    @Test public void cardCentersWithinTheViewportInsteadOfTheChatAndInventoryCanvas(){
        java.awt.Rectangle viewport=new java.awt.Rectangle(4,4,512,334);
        MatchReportLayout layout=new MatchReportLayout(viewport,1);
        assertEquals(viewport.getCenterX(),layout.x+MatchReportLayout.WIDTH*layout.scale/2,0.01);
        assertEquals(viewport.getCenterY(),layout.y+MatchReportLayout.HEIGHT*layout.scale/2,0.01);
        assertTrue(layout.y>=viewport.y+20);
        assertTrue(layout.y+MatchReportLayout.HEIGHT*layout.scale<=viewport.y+viewport.height-20);
        assertFalse(layout.contains(new Point(600,200)));assertFalse(layout.contains(new Point(200,400)));
        assertEquals(1,new MatchReportLayout(1920,1080,1).scale,0);
    }
}

package com.rankednh;

import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.image.BufferedImage;
import java.io.File;
import javax.imageio.ImageIO;

/** Renders the same component as the in-game overlay; all values are explicit preview data. */
public class MatchReportPreview
{
    public static void main(String[] args) throws Exception {
        File output=new File(args[0]);File folder=output.getParentFile();
        MatchReportView win=MatchReportView.preview();
        ImageIO.write(render(win,1024,768,2000),"png",output);
        ImageIO.write(render(win,765,503,2000),"png",new File(folder,"match-report-fixed.png"));
        MatchReportView loss=MatchReportView.preview();
        loss.title="Defeat";loss.won=false;loss.score="1 – 2";loss.delta="-27";
        loss.ratingBefore=2202;loss.ratingAfter=2175;loss.rating="2202 → 2175 rating";
        ImageIO.write(render(loss,1024,768,2000),"png",new File(folder,"match-report-defeat.png"));
        MatchReportView unrated=MatchReportView.preview();
        unrated.rank="Unranked";unrated.badge="unranked";unrated.delta="";unrated.rating="Unrated match";
        unrated.ratingBefore=null;unrated.ratingAfter=null;unrated.divisionStart=null;unrated.nextAt=null;
        unrated.progressLabel="0 / 5 placements";unrated.progressDetail="5 rated matches to reveal your rank";unrated.progress=0;
        ImageIO.write(render(unrated,765,503,2000),"png",new File(folder,"match-report-unrated.png"));
        ImageIO.write(OpponentNameplate.image("Demo Opponent"),"png",new File(folder,"opponent-nameplate-preview.png"));
        File frames=new File(folder,"match-report-frames");frames.mkdirs();
        for(int i=0;i<=60;i++)ImageIO.write(render(win,900,700,i*50L),"png",new File(frames,String.format("%03d.png",i)));
    }
    private static BufferedImage render(MatchReportView view,int width,int height,long elapsed){
        BufferedImage image=new BufferedImage(width,height,BufferedImage.TYPE_INT_RGB);
        Graphics2D g=image.createGraphics();g.setColor(new Color(48,51,54));g.fillRect(0,0,width,height);
        MatchReportAnimation.Frame frame=MatchReportAnimation.sample(view,elapsed,false);
        Rectangle viewport=width==765?new Rectangle(4,4,512,334):new Rectangle(0,0,width,height);
        if(width==765){g.setColor(new Color(27,30,34));g.fillRect(0,342,width,height-342);g.fillRect(522,0,width-522,height);
            g.setColor(new Color(159,167,164));g.drawString("Chat area · Preview",24,380);g.drawString("Inventory · Preview",548,180);}
        MatchReportRenderer.render(g,view,frame,new MatchReportLayout(viewport,frame.entrance),0,0,0);
        g.dispose();return image;
    }
}

package com.rankednh;

import org.junit.Test;
import static org.junit.Assert.*;

public class MatchReportTest
{
    private Models.Status result() {
        Models.Status s=new Models.Status();s.mode="pilot";s.player=new Models.Player();s.player.id="me";
        s.player.games=20;s.player.rating=1902.8;s.player.rank=new Models.Rank();
        s.player.rank.name="Dragonstone III";s.player.rank.badge="dragonstone_iii";s.player.rank.nextAt=1920;
        s.player.rank.nextRank="Dragonstone II";s.player.rank.pointsToNext=18;s.player.rank.progress=0.713;
        s.player.rank.divisionStart=1860;
        s.match=new Models.Match();s.match.id="match-1";s.match.state="complete";s.match.winner="me";s.match.rated=true;
        s.match.score=new int[]{2,1};s.match.opponent=new Models.Opponent();s.match.opponent.rsn="Opponent";
        s.match.ratingBefore=1864;s.match.ratingAfter=1902;s.match.ratingChange=38;return s;
    }
    @Test public void ratedReportUsesServerResultAndNextDivision(){
        MatchReportView v=MatchReportView.from(result());assertEquals("Victory",v.title);assertEquals("2 – 1",v.score);
        assertEquals("1864 → 1902 rating",v.rating);assertEquals("+38",v.delta);assertEquals("18 rating to Dragonstone II",v.progressLabel);
    }
    @Test public void firstRankNeedsAFifthRatedConfirmedResultAndAlsoCelebratesALoss(){
        Models.Status s=result();s.player.games=5;
        assertTrue(MatchReportView.from(s).placementReveal);
        s.match.winner="other";assertTrue(MatchReportView.from(s).placementReveal);
        s.match.rated=false;assertFalse(MatchReportView.from(s).placementReveal);
        s.match.rated=true;s.match.state="review";assertFalse(MatchReportView.from(s).placementReveal);
        s.match.state="void";assertFalse(MatchReportView.from(s).placementReveal);
        s.match.state="complete";s.match.ratingAfter=null;assertFalse(MatchReportView.from(s).placementReveal);
        s.match.ratingAfter=1902;s.match.ratingChange=null;assertFalse(MatchReportView.from(s).placementReveal);
        s.match.ratingChange=38;s.player.rank.badge="unranked";assertFalse(MatchReportView.from(s).placementReveal);
        s.player.rank.badge="dragonstone_iii";s.player.games=4;assertFalse(MatchReportView.from(s).placementReveal);
        s.player.games=6;assertFalse(MatchReportView.from(s).placementReveal);
    }
    @Test public void defeatKeepsTheNegativeRatingChange(){
        Models.Status s=result();s.match.winner="other";s.match.ratingChange=-27;s.match.ratingBefore=1929;
        MatchReportView v=MatchReportView.from(s);assertEquals("Defeat",v.title);assertEquals("-27",v.delta);
    }
    @Test public void unrankedAndUnratedNeverInventRatingGains(){
        Models.Status s=result();s.match.rated=false;
        assertEquals("",MatchReportView.from(s).delta);assertEquals("Unrated match",MatchReportView.from(s).rating);
        s.match.rated=true;s.player.games=4;s.player.rank.name="Unranked";
        MatchReportView v=MatchReportView.from(s);assertEquals("",v.delta);assertEquals("4 / 5 placements",v.progressLabel);
        assertEquals("1 rated match to reveal your rank",v.progressDetail);
    }
    @Test public void pendingAndVoidedOutcomesDoNotClaimVictory(){
        Models.Status s=result();s.match.state="review";
        assertEquals("Result pending",MatchReportView.from(s).title);assertEquals("",MatchReportView.from(s).delta);
        s.match.state="void";assertEquals("Match voided",MatchReportView.from(s).title);
        s.match.state="active";assertNull(MatchReportView.from(s));
    }
    @Test public void highestRankHasNoInventedNextBracket(){
        Models.Status s=result();s.player.rank.nextAt=null;s.player.rank.nextRank=null;
        MatchReportView v=MatchReportView.from(s);assertEquals("Highest division reached",v.progressLabel);assertEquals(1,v.progress,0);
    }
    private Models.Rank rank(String name,String badge,int start,Integer next,String nextRank){
        Models.Rank rank=new Models.Rank();rank.name=name;rank.badge=badge;rank.divisionStart=start;
        rank.nextAt=next;rank.nextRank=nextRank;return rank;
    }
    @Test public void realPromotionUsesTheMatchSnapshotsAndIncludesTheHighestDivision(){
        Models.Status s=result();s.match.ratingBefore=1799;s.match.ratingAfter=1826;s.match.ratingChange=27;
        s.match.rankBefore=rank("Diamond II","diamond_ii",1740,1800,"Diamond I");
        s.match.rankAfter=rank("Diamond I","diamond_i",1800,1860,"Dragonstone III");
        MatchReportView view=MatchReportView.from(s);assertTrue(view.promotion());
        assertEquals("diamond_ii",view.badgeBefore);assertEquals("diamond_i",view.badge);assertEquals(26/60.0,view.progress,.0001);
        // The current player rank is deliberately different; the awarded result wins.
        s.match.rankBefore=rank("Zenyte II","zenyte_ii",2280,2340,"Zenyte I");
        s.match.rankAfter=rank("Zenyte I","zenyte_i",2340,null,null);
        s.match.ratingBefore=2339;s.match.ratingAfter=2366;
        view=MatchReportView.from(s);assertTrue(view.promotion());
        assertEquals("Highest division reached",view.progressLabel);
        assertEquals(1,MatchReportAnimation.sample(view,5000,false).progress,0);
        s.match.rated=false;assertFalse(MatchReportView.from(s).promotion());
        s.match.rated=true;s.match.state="review";assertFalse(MatchReportView.from(s).promotion());
    }
    @Test public void storedFirstRankStaysAPlacementRevealAndDemotionsDoNotCelebrate(){
        Models.Status s=result();s.match.rankBefore=rank("Unranked","unranked",0,null,null);
        s.match.rankBefore.divisionStart=null;s.match.rankAfter=s.player.rank;
        assertTrue(MatchReportView.from(s).placementReveal);assertFalse(MatchReportView.from(s).promotion());
        s.match.rankBefore=rank("Dragonstone II","dragonstone_ii",1920,1980,"Dragonstone I");
        s.match.ratingBefore=1921;s.match.ratingAfter=1902;s.match.ratingChange=-19;
        assertFalse(MatchReportView.from(s).placementReveal);assertFalse(MatchReportView.from(s).promotion());
        s.match.rankBefore=null;s.match.rankAfter=null;
        assertFalse(MatchReportView.from(s).promotion());
    }
    @Test public void pollingDoesNotResetDismissalOrExpiry(){
        Models.Status s=result();MatchReportVisibility visibility=new MatchReportVisibility();
        assertTrue(visibility.visible(s,0,60));assertTrue(visibility.visible(s,59_000,60));assertFalse(visibility.visible(s,60_000,60));
        visibility.reopen();assertTrue(visibility.visible(s,61_000,60));visibility.dismiss();assertFalse(visibility.visible(s,62_000,60));
        s.match.id="match-2";assertTrue(visibility.visible(s,63_000,60));
    }
    @Test public void resolvedReviewShowsNewResultAndQueueHidesOldReport(){
        Models.Status s=result();s.match.state="review";MatchReportVisibility visibility=new MatchReportVisibility();
        assertFalse(visibility.visible(s,0,0));visibility.reopen();assertTrue(visibility.visible(s,0,0));visibility.dismiss();s.match.state="complete";assertTrue(visibility.visible(s,500,0));
        s.queued=true;assertFalse(visibility.visible(s,600,0));
    }
    @Test public void previewIsExplicitAndNeverConsumesARealResult(){
        MatchReportView v=MatchReportView.preview();assertTrue(v.preview);assertTrue(v.heading.contains("Preview"));
        assertTrue(v.note.contains("unchanged"));
    }
    @Test public void countAndBarStartAtPreviousRatingAndFinishAtConfirmedRating(){
        MatchReportView v=MatchReportView.from(result());
        MatchReportAnimation.Frame start=MatchReportAnimation.sample(v,0,false);
        assertEquals(Integer.valueOf(1864),start.rating);assertEquals(4/60.0,start.progress,0.00001);assertEquals(0,start.entrance,0);
        MatchReportAnimation.Frame middle=MatchReportAnimation.sample(v,900,false);
        assertTrue(middle.rating>1864 && middle.rating<1902);assertTrue(middle.progress>start.progress && middle.progress<0.7);
        MatchReportAnimation.Frame end=MatchReportAnimation.sample(v,1800,false);
        assertEquals(Integer.valueOf(1902),end.rating);assertEquals(0.7,end.progress,0.00001);
        assertEquals("18 rating to Dragonstone II",end.progressLabel);
    }
    @Test public void lossCountsDownAndClampsProgressToTheConfirmedDivision(){
        Models.Status s=result();s.match.ratingBefore=1929;s.match.ratingChange=-27;s.match.winner="other";
        MatchReportView v=MatchReportView.from(s);
        assertEquals(1,MatchReportAnimation.sample(v,0,false).progress,0);
        MatchReportAnimation.Frame middle=MatchReportAnimation.sample(v,900,false);
        assertTrue(middle.rating<1929 && middle.rating>1902);
        assertEquals(0.7,MatchReportAnimation.sample(v,1800,false).progress,0.00001);
        s.match.ratingBefore=1800;s.match.ratingChange=102;v=MatchReportView.from(s);
        assertEquals(0,MatchReportAnimation.sample(v,0,false).progress,0);
        assertEquals(0.7,MatchReportAnimation.sample(v,1800,false).progress,0.00001);
    }
    @Test public void animationSurvivesPollingAndReplaysOnlyForANewResultOrReopen(){
        MatchReportAnimation animation=new MatchReportAnimation();MatchReportView v=MatchReportView.preview();
        animation.frame("one",v,100,false);
        assertEquals(Integer.valueOf(2202),animation.frame("one",MatchReportView.preview(),2000,false).rating);
        assertEquals(Integer.valueOf(2202),animation.frame("one",v,6000,false).rating);
        assertEquals(Integer.valueOf(2164),animation.frame("two",v,6000,false).rating);
        animation.reset();assertEquals(Integer.valueOf(2164),animation.frame("two",v,7000,false).rating);
    }
    @Test public void reducedMotionImmediatelyShowsTheFinalValues(){
        MatchReportAnimation.Frame frame=MatchReportAnimation.sample(MatchReportView.preview(),0,true);
        assertEquals(Integer.valueOf(2202),frame.rating);assertEquals(0.7,frame.progress,0.00001);assertEquals(1,frame.entrance,0);
    }
    @Test public void hiddenOrUnconfirmedRatingsNeverCount(){
        Models.Status s=result();s.match.rated=false;
        assertNull(MatchReportAnimation.sample(MatchReportView.from(s),900,false).rating);
        s.match.rated=true;s.player.games=4;
        assertNull(MatchReportAnimation.sample(MatchReportView.from(s),900,false).rating);
        s.player.games=20;s.match.state="review";
        assertNull(MatchReportAnimation.sample(MatchReportView.from(s),900,false).rating);
        s.match.state="complete";s.match.ratingChange=null;
        assertNull(MatchReportAnimation.sample(MatchReportView.from(s),900,false).rating);
    }
}

