        for(int i=0;i<100;i++){spins.prepare("diamond_i");assertNull(spins.frame("diamond_i",.4));}
        assertEquals(1,loads.get());spins.prepare("../../other");assertEquals(1,loads.get());
        assertFalse(RankSpinImages.supported("unranked"));
